.latents_select_screened <- function(screened, continued, finalists,
                                     screened_scores, select_start,
                                     score = function(attempt) {
                                       attempt$expectation$log_likelihood
                                     }, interior = NULL) {
  pool <- seq_along(screened)
  attempts <- lapply(screened, function(attempt) {
    attempt$checkpoint <- NULL
    attempt
  })
  attempts[finalists] <- lapply(continued, function(attempt) {
    attempt$checkpoint <- NULL
    attempt
  })
  stage <- ifelse(pool %in% finalists, "final", "screened")
  valid <- vapply(attempts, function(attempt) is.null(attempt$error), logical(1))
  final_valid <- valid & stage == "final"
  if (!any(final_valid)) {
    stop(.latents_start_failure(sprintf(
      "All %d starts carried to the end failed: %s", length(finalists),
      paste(unique(vapply(attempts[finalists], `[[`, character(1), "error")),
            collapse = "; ")),
      c(screened, continued)))
  }
  scores <- vapply(seq_along(attempts), function(start_index) {
    attempt <- attempts[[start_index]]
    if (!valid[start_index]) -Inf else if (final_valid[start_index]) score(attempt) else
      attempt$expectation$log_likelihood
  }, numeric(1))
  converged <- vapply(attempts, function(attempt) isTRUE(attempt$converged),
                      logical(1))
  # Only a start run to the end can be reported.
  eligible_scores <- ifelse(final_valid, scores, -Inf)
  flags <- if (!is.null(interior)) {
    vapply(seq_along(attempts), function(start_index) {
      final_valid[start_index] && isTRUE(interior(attempts[[start_index]]))
    }, logical(1))
  }
  result <- list(attempts = attempts, valid = valid, scores = scores,
                 converged = converged, stage = stage, screened_scores = screened_scores,
                 best_start = .multilpa_select_start(eligible_scores, converged & final_valid,
                                                     select_start, flags))
  # A finalist replaces its screened attempt, but both phases contributed
  # covariance M-steps to the fit's qualification. Keep those counts separately.
  logs <- lapply(c(screened, continued), attr, which = "lta_structure_log")
  if (any(!vapply(logs, is.null, logical(1)))) attr(result, "lta_structure_logs") <- logs
  result
}

.latents_quasi_newton <- function(theta, lower, value, gradient, tol, control) {
  theta <- pmax(theta, lower)
  start_value <- value(theta)
  found <- stats::optim(theta, value, gradient, method = "L-BFGS-B",
                        lower = lower, control = control)
  if (!is.finite(found$value) || found$value > start_value) {
    return(list(par = theta, value = start_value, converged = FALSE,
                improved = FALSE, start_value = start_value))
  }
  converged <- found$convergence == 0L
  if (identical(found$convergence, 52L)) {
    again <- stats::optim(found$par, value, gradient, method = "L-BFGS-B",
                          lower = lower, control = control)
    if (is.finite(again$value) && again$value <= found$value) {
      converged <- again$convergence == 0L ||
        found$value - again$value <= tol * (1 + abs(again$value))
      found <- again
    }
  }
  list(par = found$par, value = found$value, converged = converged,
       improved = TRUE, start_value = start_value)
}

.mixture_row_lse <- function(log_values) {
  # pmax() over the columns is the row maximum without a per-row R call.
  row_max <- do.call(pmax, lapply(seq_len(ncol(log_values)), function(k) {
    log_values[, k]
  }))
  finite <- is.finite(row_max)
  if (all(finite)) return(row_max + log(rowSums(exp(log_values - row_max))))
  out <- row_max
  out[finite] <- row_max[finite] +
    log(rowSums(exp(log_values[finite, , drop = FALSE] - row_max[finite])))
  out
}

.mixture_log_softmax <- function(design, coefficients) {
  scores <- design %*% coefficients
  scores - .mixture_row_lse(scores)
}

.mixture_weigh <- function(spec, expectation) {
  unit_weights <- spec$sampling_weights
  row_weights <- spec$row_weights
  # Classes at the row level are weighted per row; the units the likelihood
  # sums over are rows, or clusters when `id` names them.
  expectation$log_likelihood <- if (identical(spec$nesting, "observation")) {
    sum(row_weights * expectation$unit_log_likelihood)
  } else sum(unit_weights * expectation$unit_log_likelihood)
  expectation$tau <- expectation$tau * row_weights
  if (!is.null(expectation$group_tau)) {
    expectation$group_tau <- expectation$group_tau * unit_weights
  }
  if (!is.null(expectation$rho)) {
    expectation$rho <- expectation$rho * unit_weights
    expectation$tau_by_group_class <- lapply(expectation$tau_by_group_class,
                                             `*`, row_weights)
  }
  expectation
}

outputs.terminal_expression:
switch(spec$nesting, observation = {
    log_prior <- .mixture_log_softmax(spec$w, params$gamma)
    joint <- log_prior + log_density
    unit <- .mixture_row_lse(joint)
    list(log_likelihood = sum(unit), unit_log_likelihood = unit, tau = exp(joint - unit), log_prior = log_prior, log_density = log_density)
}, group = {
    log_prior <- .mixture_log_softmax(spec$w, params$gamma)
    joint <- log_prior + rowsum(log_density, spec$group_index, reorder = TRUE)
    unit <- .mixture_row_lse(joint)
    group_tau <- exp(joint - unit)
    list(log_likelihood = sum(unit), unit_log_likelihood = unit, tau = group_tau[spec$group_index, , drop = FALSE], group_tau = group_tau, 
        log_prior = log_prior, log_density = log_density)
}, `two-level` = {
    log_eta <- .mixture_log_softmax(spec$v, params$delta)
    n_group_classes <- ncol(log_eta)
    within <- lapply(seq_len(n_group_classes), function(h) {
        log_prior <- .mixture_log_softmax(.mixture_two_level_design(spec, h), params$class_logits)
        joint <- log_prior + log_density
        marginal <- .mixture_row_lse(joint)
        list(log_prior = log_prior, joint = joint, marginal = marginal)
    })
    group_log <- log_eta + vapply(within, function(piece) {
        drop(rowsum(piece$marginal, spec$group_index, reorder = TRUE))
    }, numeric(spec$n_groups))
    unit <- .mixture_row_lse(group_log)
    rho <- exp(group_log - unit)
    tau_by_group_class <- lapply(seq_len(n_group_classes), function(h) {
        rho[spec$group_index, h] * exp(within[[h]]$joint - within[[h]]$marginal)
    })
    list(log_likelihood = sum(unit), unit_log_likelihood = unit, tau = Reduce(`+`, tau_by_group_class), rho = rho, tau_by_group_class = tau_by_group_class, 
        log_prior_by_group_class = lapply(within, `[[`, "log_prior"), log_eta = log_eta, log_density = log_density)
})

mathematical_conventions.formula_or_effect_source:
.mixture_two_level_design <- function(spec, h) {
  indicator <- matrix(0, spec$n, spec$n_group_classes)
  indicator[, h] <- 1
  cbind(indicator, spec$w)
}

.mixture_solve <- function(a, b) {
  factor <- tryCatch(chol(a), error = function(e) NULL)
  if (!is.null(factor)) return(backsolve(factor, forwardsolve(t(factor), b)))
  qr.solve(a, b, tol = 1e-12)
}

.mixture_update_mixing <- function(spec, params, expectation) {
  closed_form <- function(counts) {
    shares <- pmax(colSums(counts), .Machine$double.xmin)
    matrix(log(shares) - log(shares[1L]), nrow = 1L)
  }
  switch(spec$nesting,
    observation = ,
    group = {
      counts <- if (identical(spec$nesting, "group")) expectation$group_tau else
        expectation$tau
      if (spec$intercept_only) {
        params$gamma <- closed_form(counts)
      } else {
        fit <- .mixture_multinomial(spec$w, counts, params$gamma)
        params$gamma <- fit$coefficients
        params$membership_separation <- fit$separation
      }
    },
    "two-level" = {
      if (spec$group_intercept_only) {
        params$delta <- closed_form(expectation$rho)
      } else {
        fit <- .mixture_multinomial(spec$v, expectation$rho, params$delta)
        params$delta <- fit$coefficients
        params$group_separation <- fit$separation
      }
      if (ncol(spec$w) == 0L) {
        # Intercepts only: each group class's class shares are closed form.
        params$class_logits <- do.call(rbind, lapply(
          expectation$tau_by_group_class, closed_form))
      } else {
        design <- do.call(rbind, lapply(seq_len(spec$n_group_classes),
                                        function(h) {
          .mixture_two_level_design(spec, h)
        }))
        counts <- do.call(rbind, expectation$tau_by_group_class)
        fit <- .mixture_multinomial(design, counts, params$class_logits)
        params$class_logits <- fit$coefficients
        params$membership_separation <- fit$separation
      }
    })
  params
}

.mixture_structure_scores <- function(spec, expectation) {
  tau <- expectation$tau
  to_units <- function(scores) {
    if (identical(spec$nesting, "observation")) scores else
      rowsum(scores, spec$group_index, reorder = TRUE)
  }
  mixing <- switch(spec$nesting,
    observation = {
      residual <- tau - rowSums(tau) * exp(expectation$log_prior)
      do.call(cbind, lapply(seq.int(2L, length.out = spec$n_classes - 1L),
                            function(k) spec$w * residual[, k]))
    },
    group = {
      residual <- expectation$group_tau -
        rowSums(expectation$group_tau) * exp(expectation$log_prior)
      do.call(cbind, lapply(seq.int(2L, length.out = spec$n_classes - 1L),
                            function(k) spec$w * residual[, k]))
    },
    "two-level" = {
      rho <- expectation$rho
      group_residual <- rho - rowSums(rho) * exp(expectation$log_eta)
      delta_scores <- do.call(cbind, lapply(
        seq.int(2L, length.out = spec$n_group_classes - 1L),
        function(h) spec$v * group_residual[, h]))
      # Row-level class-logit scores, summed to groups below.
      residual_by_group_class <- lapply(
        seq_len(spec$n_group_classes), function(h) {
          expectation$tau_by_group_class[[h]] -
            rho[spec$group_index, h] *
            exp(expectation$log_prior_by_group_class[[h]])
        })
      logit_scores <- do.call(cbind, lapply(
        seq.int(2L, length.out = spec$n_classes - 1L), function(k) {
          intercepts <- vapply(residual_by_group_class, function(r) r[, k],
                               numeric(spec$n))
          intercepts <- matrix(intercepts, spec$n)
          slopes <- spec$w * Reduce(`+`, lapply(residual_by_group_class,
                                                function(r) r[, k]))
          cbind(intercepts, slopes)
        }))
      cbind(delta_scores %||% matrix(0, spec$n_groups, 0L),
            to_units(logit_scores %||% matrix(0, spec$n, 0L)))
    })
  # One class (and one group class) has no free membership coefficients.
  mixing %||% matrix(0, if (identical(spec$nesting, "observation"))
    spec$n else spec$n_groups, 0L)
}

.latents_forward_backward <- function(emission, layout, log_initial, log_transition) {
  if (is.matrix(log_transition)) {
    return(.latents_scaled_forward_backward(emission, layout, exp(log_initial),
                                            exp(log_transition)))
  }
  n_groups <- nrow(layout$slot)
  n_profiles <- ncol(log_initial)
  later <- seq_len(layout$n_occasions)[-1L]
  hold <- function(updated, previous, occasion) {
    outside <- !layout$within[, occasion]
    if (any(outside)) updated[outside, ] <- previous[outside, , drop = FALSE]
    updated
  }
  forward_step <- function(state, transition) {
    matrix(vapply(seq_len(n_profiles), function(to) {
      .latents_log_sum_exp(state + transition[, , to])
    }, numeric(n_groups)), n_groups, n_profiles)
  }
  backward_step <- function(state, transition) {
    matrix(vapply(seq_len(n_profiles), function(from) {
      .latents_log_sum_exp(state + matrix(transition[, from, ], n_groups, n_profiles))
    }, numeric(n_groups)), n_groups, n_profiles)
  }
  alpha <- Reduce(function(previous, t) {
    hold(forward_step(previous, log_transition[[t - 1L]]) + emission[[t]],
         previous, t)
  }, later, init = log_initial + emission[[1L]], accumulate = TRUE)
  beta <- Reduce(function(t, following) {
    hold(backward_step(following + emission[[t]], log_transition[[t - 1L]]),
         following, t)
  }, later, init = matrix(0, n_groups, n_profiles), right = TRUE, accumulate = TRUE)
  if (!is.list(alpha)) alpha <- list(alpha)
  if (!is.list(beta)) beta <- list(beta)
  list(alpha = alpha, beta = beta,
       log_scaled = .latents_log_sum_exp(alpha[[layout$n_occasions]]))
}

.latents_log_sum_exp <- function(values) {
  top <- .multilpa_row_max(values)
  finite <- is.finite(top)
  out <- rep(-Inf, nrow(values))
  if (any(finite)) {
    shifted <- exp(values[finite, , drop = FALSE] - top[finite])
    out[finite] <- top[finite] + log(rowSums(shifted))
  }
  out
}

.mixture_structure_pack <- function(spec, params) {
  # paste0() recycles a zero-length argument to one string, so an empty block
  # (one class, no group-class covariates) must be named explicitly as empty.
  labelled <- function(values, labels) {
    if (length(values) == 0L) numeric() else stats::setNames(values, labels)
  }
  class_names <- paste0("class_", seq_len(spec$n_classes))
  free_classes <- class_names[-1L]
  mixing <- if (identical(spec$nesting, "two-level")) {
    group_names <- paste0("group_class_", seq_len(spec$n_group_classes))
    delta <- params$delta[, -1L, drop = FALSE]
    logits <- params$class_logits[, -1L, drop = FALSE]
    logit_rows <- c(paste0("(Intercept):", group_names), colnames(spec$w))
    c(labelled(as.vector(delta), paste0(
      "group_membership.", rep(group_names[-1L], each = ncol(spec$v)), ".",
      rep(colnames(spec$v), spec$n_group_classes - 1L))),
      labelled(as.vector(logits), paste0(
        "membership.", rep(free_classes, each = length(logit_rows)), ".",
        rep(logit_rows, length(free_classes)))))
  } else {
    gamma <- params$gamma[, -1L, drop = FALSE]
    labelled(as.vector(gamma), paste0(
      "membership.", rep(free_classes, each = ncol(spec$w)), ".",
      rep(colnames(spec$w), length(free_classes))))
  }
  mixing
}

.mixture_structure_unpack <- function(spec, values, template) {
  k <- spec$n_classes
  position <- 0L
  take <- function(count) {
    taken <- values[position + seq_len(count)]
    position <<- position + count
    unname(taken)
  }
  # Filled in place, so the template's shapes and names are kept.
  params <- template
  if (identical(spec$nesting, "two-level")) {
    params$delta[] <- cbind(0, matrix(take(ncol(spec$v) * (spec$n_group_classes - 1L)),
                                      ncol(spec$v)))
    params$class_logits[] <- cbind(0, matrix(take(nrow(template$class_logits) * (k - 1L)),
                                             nrow(template$class_logits)))
  } else {
    params$gamma[] <- cbind(0, matrix(take(ncol(spec$w) * (k - 1L)), ncol(spec$w)))
  }
  stopifnot("the membership coefficients must be consumed exactly" =
              position == length(values))
  params
}

.latents_parse_pairs <- function(local_dependence) {
  refuse <- function(message) {
    stop(errorCondition(message, class = "latents_bad_argument", call = NULL))
  }
  if (!(is.character(local_dependence) && !anyNA(local_dependence))) {
    refuse("`local_dependence` names pairs of indicators, such as \"item1:item2\".")
  }
  parts <- strsplit(local_dependence, ":", fixed = TRUE)
  if (!all(lengths(parts) == 2L) || any(!nzchar(unlist(parts)))) {
    refuse(sprintf(paste(
      "Each pair in `local_dependence` is two indicator names joined by a colon,",
      "such as \"item1:item2\"; %s is not."),
      paste(sprintf("\"%s\"", local_dependence[lengths(parts) != 2L |
                                                 vapply(parts, \(p) any(!nzchar(p)), logical(1))]),
            collapse = ", ")))
  }
  pairs <- data.frame(item_1 = vapply(parts, `[[`, "", 1L),
                      item_2 = vapply(parts, `[[`, "", 2L),
                      stringsAsFactors = FALSE)
  pairs$name <- paste(pairs$item_1, pairs$item_2, sep = ":")
  if (any(pairs$item_1 == pairs$item_2)) refuse("A pair in `local_dependence` names one indicator twice.")
  items <- c(pairs$item_1, pairs$item_2)
  if (anyDuplicated(items) > 0L) {
    refuse(sprintf(paste(
      "An indicator can be in one pair of `local_dependence` only; %s is in more.",
      "A dependence among three items needs their joint table."),
      paste(sprintf("`%s`", unique(items[duplicated(items)])), collapse = ", ")))
  }
  pairs
}

.latents_classify_pairs <- function(pairs, categorical) {
  first <- pairs$item_1 %in% categorical
  second <- pairs$item_2 %in% categorical
  if (any(first != second)) {
    stop(errorCondition(sprintf(paste(
      "A pair in `local_dependence` joins items of the same kind: two",
      "categorical items, modelled jointly, or two continuous ones, given a",
      "covariance. %s mixes the two."),
      paste(sprintf("\"%s\"", pairs$name[first != second]), collapse = ", ")),
      class = "latents_bad_argument", call = NULL))
  }
  pairs$kind <- ifelse(first, "categorical", "continuous")
  pairs
}

.latents_covariance_pattern <- function(pairs, vars, categorical, ordinal, count,
                                        conflicts) {
  continuous <- setdiff(vars, c(categorical, ordinal, count))
  items <- c(pairs$item_1, pairs$item_2)
  absent <- setdiff(items, continuous)
  if (length(absent) > 0L) {
    stop(errorCondition(sprintf(paste(
      "`local_dependence` names %s, which %s not a continuous indicator among",
      "`vars`; pair two categorical items, or two continuous ones."),
      paste(sprintf("`%s`", absent), collapse = ", "),
      if (length(absent) > 1L) "are" else "is"), class = "latents_bad_argument", call = NULL))
  }
  if (any(conflicts)) {
    stop(errorCondition(sprintf(paste(
      "A covariance for chosen pairs of continuous indicators sets the",
      "covariance itself; it is not combined with %s."),
      paste(sprintf("`%s`", names(conflicts)[conflicts]), collapse = ", ")),
      class = "latents_bad_argument", call = NULL))
  }
  pattern <- diag(length(continuous)) > 0
  dimnames(pattern) <- list(continuous, continuous)
  pattern[cbind(pairs$item_1, pairs$item_2)] <- TRUE
  pattern[cbind(pairs$item_2, pairs$item_1)] <- TRUE
  pattern
}

.latents_pattern_pairs <- function(pattern) {
  pairs <- which(pattern & upper.tri(pattern), arr.ind = TRUE)
  paste(rownames(pattern)[pairs[, "row"]], colnames(pattern)[pairs[, "col"]], sep = ":")
}

.latents_pattern_label <- function(fit) {
  sprintf("%s + %s", if (identical(fit$variance_model, "equal")) "EEI" else "VVI",
          paste(.latents_pattern_pairs(fit$covariance_pattern), collapse = ", "))
}

.latents_mask_covariances <- function(parameters, pattern) {
  if (is.null(pattern) || is.null(parameters$covariances)) return(parameters)
  masked <- parameters$covariances
  masked[!array(pattern, dim(masked))] <- 0
  parameters$covariances <- masked
  parameters
}

.latents_pattern_zeros <- function(pattern) {
  sum(lower.tri(pattern) & !pattern)
}

.latents_joined_names <- function(vars, pairs) {
  vars[match(pairs$item_1, vars)] <- pairs$name
  setdiff(vars, pairs$item_2)
}

.latents_categorical_labels <- function(fit) {
  # A general lta() fit keeps its categorical codes as `codes`.
  codes <- fit$categorical_data %||% fit$codes
  if (is.null(codes) || ncol(codes) == 0L) return(NULL)
  labels <- lapply(colnames(codes), function(name) {
    fit$categorical_levels[[name]][codes[, name]]
  })
  names(labels) <- colnames(codes)
  pairs <- fit$local_dependence
  if (!is.null(pairs)) {
    labels <- unlist(lapply(names(labels), function(name) {
      if (!name %in% pairs$name) return(stats::setNames(list(labels[[name]]), name))
      categories <- fit$local_dependence_categories[[name]]
      at <- match(labels[[name]], categories$label)
      pair <- pairs[pairs$name == name, ]
      stats::setNames(list(categories$level_1[at], categories$level_2[at]),
                      c(pair$item_1, pair$item_2))
    }), recursive = FALSE)
    labels <- labels[fit$original_categorical]
  }
  do.call(cbind, labels)
}

.multilpa_pool_fallback <- function(arguments) {
  if (length(arguments$profile_covariates) || length(arguments$group_covariates)) {
    return(TRUE)
  }
  length(arguments$local_dependence) > 0L &&
    any(.latents_parse_pairs(arguments$local_dependence)$item_1 %in%
          arguments$categorical)
}

.multilpa_pool_width <- function(data, vars, extra) {
  stopifnot("data is a data frame" = is.data.frame(data),
            "vars are indicator names" = is.character(vars))
  discrete <- intersect(intersect(vars, names(data)), c(extra$categorical, extra$ordinal))
  category_width <- sum(vapply(discrete, function(name) {
    max(1, length(unique(data[[name]][!is.na(data[[name]])])) - 1)
  }, numeric(1)))
  # Means and variances (or a count mean and dispersion) give two entries;
  # categorical probabilities contribute one fewer than their observed levels.
  max(1, category_width + 2 * length(setdiff(vars, discrete)))
}

