    block <- response_probabilities[[indicator]]
    if (!is.matrix(block) || !is.numeric(block) || !identical(as.integer(dim(block)), c(as.integer(n_profiles), as.integer(n_categories[[indicator]]))) || 
        any(!is.finite(block))) {
        stop(errorCondition(sprintf("start$response_probabilities[[%d]] must be a finite numeric %d x %d matrix.", indicator, 
            n_profiles, n_categories[[indicator]]), class = "latents_bad_start", call = NULL))
    }
    if (any(block < 0) || any(abs(rowSums(block) - 1) > 1e-08)) {
        stop(errorCondition(sprintf("start$response_probabilities[[%d]] rows must be nonnegative and sum to one.", indicator), 
            class = "latents_bad_start", call = NULL))
    }
    bounded <- t(apply(block/rowSums(block), 1L, .multilpa_bound_probabilities, min_probability = min_probability))
    matrix(bounded, n_profiles, n_categories[[indicator]])
}))

