.latents_pool_setup <- function(tasks, setup, costs, cores, distribute) {
  stopifnot("`setup` must be a function" = is.function(setup),
            "one cost per setup task" = length(costs) == length(tasks),
            "`distribute` must be TRUE or FALSE" =
              isTRUE(distribute) || isFALSE(distribute))
  if (!distribute || cores <= 1L || length(tasks) <= 1L) {
    return(lapply(tasks, function(task) {
      .latents_collect_conditions(function() setup(task))
    }))
  }
  .latents_map_candidates(tasks, setup, cores, costs = costs, signal = FALSE,
    on_lost = function(task, message) {
      errorCondition(message, class = "latents_candidate_failed", call = NULL)
    })
}

.latents_pool_progress <- function(verbose, format, ...) {
  if (isTRUE(verbose)) {
    # Base R has no messageCondition(); this is the same structure.
    message(structure(class = c("latents_progress", "message", "condition"),
                      list(message = paste0(sprintf(format, ...), "\n"), call = NULL)))
  }
  invisible(NULL)
}

.latents_count <- function(n, noun) {
  n <- as.integer(n)
  sprintf("%d %s%s", n, noun, if (identical(n, 1L)) "" else "s")
}

.latents_format_duration <- function(seconds) {
  stopifnot("`seconds` must be one non-negative number" =
              is.numeric(seconds) && length(seconds) == 1L && !is.na(seconds) &&
              seconds >= 0)
  minutes <- as.integer(round(seconds / 60))
  if (minutes < 1L) return("under a minute")
  if (minutes < 60L) return(sprintf("%d min", minutes))
  sprintf("%d h %d min", minutes %/% 60L, minutes %% 60L)
}

.multilpa_any_fit <- function(object) {
  inherits(object, "multilpa") || inherits(object, "multilpa_covariates") ||
    inherits(object, "multilpa_transitions")
}

.multilpa_is_seed <- function(seed) {
  if (!is.numeric(seed)) return(rep(FALSE, length(seed)))
  finite <- is.finite(seed)
  finite & abs(ifelse(finite, seed, 0)) <= .Machine$integer.max &
    ifelse(finite, seed == trunc(seed), FALSE)
}

.multilpa_check_seed <- function(seed) {
  if (is.null(seed) || (length(seed) == 1L && .multilpa_is_seed(seed))) {
    return(invisible(NULL))
  }
  stop(errorCondition(sprintf(
    "`seed` must be NULL or a single whole number between -%d and %d.",
    .Machine$integer.max, .Machine$integer.max),
    class = "latents_bad_argument", call = NULL))
}

.multilpa_select_start <- function(log_likelihood, converged,
                                   rule = c("likelihood", "converged"),
                                   interior = NULL) {
  rule <- match.arg(rule)
  stopifnot(
    "`log_likelihood` must be numeric" = is.numeric(log_likelihood),
    "`converged` must be logical and match `log_likelihood`" =
      is.logical(converged) && length(converged) == length(log_likelihood),
    "at least one start must have a finite likelihood" =
      any(is.finite(log_likelihood)),
    "`interior` must be NULL or logical and match `log_likelihood`" =
      is.null(interior) || (is.logical(interior) &&
        length(interior) == length(log_likelihood) && !anyNA(interior))
  )
  usable <- is.finite(log_likelihood)
  if (!is.null(interior)) {
    if (any(usable & interior)) {
      usable <- usable & interior
    } else {
      warning(warningCondition(paste(
        "Every start reached a variance at its lower bound, so none could be",
        "excluded; the best start across all of them is reported."),
        class = "latents_all_starts_boundary", call = NULL))
    }
  }
  settled <- usable & converged
  candidates <- if (identical(rule, "converged") && any(settled)) {
    which(settled)
  } else which(usable)
  best <- max(log_likelihood[candidates])
  tied <- candidates[log_likelihood[candidates] >= best - 1e-10 * (1 + abs(best))]
  preferred <- tied[converged[tied]]
  if (length(preferred) > 0L) preferred[1L] else tied[1L]
}

.multilpa_row_max <- function(x) {
  stopifnot("`x` must be a numeric matrix" = is.matrix(x) && is.numeric(x))
  if (ncol(x) == 0L) return(rep(-Inf, nrow(x)))
  do.call(pmax, lapply(seq_len(ncol(x)), function(column) x[, column]))
}

.multilpa_notice <- function(text, class) {
  condition <- structure(list(message = paste0(text, "\n"), call = NULL),
                         class = c(class, "message", "condition"))
  message(condition)
  invisible(NULL)
}

.multilpa_single_level_notice <- function(latent_class = FALSE) {
  analysis <- if (isTRUE(latent_class)) "latent class" else "latent profile"
  .multilpa_notice(sprintf("Fitted a single-level %s model.", analysis),
    class = "latents_single_level")
  invisible(NULL)
}

.multilpa_missing_id <- function(verb, single) {
  stop(errorCondition(sprintf(
    "`%s()` needs `id` (grouping column). For single-level data use %s.",
    verb, single),
    class = "latents_bad_argument", call = NULL))
}

.latents_sampling_weights <- function(data, weights, group_index, n_groups) {
  if (is.null(weights)) return(NULL)
  if (!is.character(weights) || length(weights) != 1L || is.na(weights) ||
      !weights %in% names(data)) {
    stop(errorCondition(
      "`weights` must name one column of `data` holding a sampling weight per unit.",
      class = "latents_bad_weights", call = NULL))
  }
  values <- data[[weights]]
  if (!is.numeric(values) || anyNA(values) || any(!is.finite(values)) ||
      any(values < 0)) {
    stop(errorCondition(sprintf(
      "Sampling weights in `%s` must be finite, non-missing and non-negative.",
      weights), class = "latents_bad_weights", call = NULL))
  }
  stopifnot("one unit per row" = length(group_index) == length(values))
  unit <- as.vector(tapply(values, group_index, min))
  spread <- as.vector(tapply(values, group_index, max)) - unit
  if (any(spread > sqrt(.Machine$double.eps) * pmax(1, abs(unit)))) {
    stop(errorCondition(sprintf(paste(
      "Sampling weights in `%s` vary inside a unit. The pseudo likelihood",
      "weights the independent units (the `id` groups, or the rows of a",
      "single-level fit); a within-unit weight is not supported."), weights),
      class = "latents_bad_weights", call = NULL))
  }
  if (sum(unit) <= 0 || sum(unit > 0) < 2L) {
    stop(errorCondition(sprintf(
      "Sampling weights in `%s` must be positive for at least two units.", weights),
      class = "latents_bad_weights", call = NULL))
  }
  stopifnot("one weight per unit" = length(unit) == n_groups)
  # Normalize before summing or multiplying: finite raw weights can overflow
  # both operations even though their relative weights are well defined.
  relative <- unit / max(unit)
  relative * (n_groups / sum(relative))
}

.latents_refuse_weights <- function(what) {
  stop(errorCondition(sprintf(paste(
    "Sampling weights are not supported with %s."), what),
    class = "latents_unsupported_weights", call = NULL))
}

.latents_weighted_vcov <- function(weighted, vcov_type, defaulted) {
  if (!isTRUE(weighted)) return(vcov_type)
  if (defaulted) return("robust")
  if (!identical(vcov_type, "robust")) {
    stop(errorCondition(sprintf(paste(
      "A fit with sampling weights is a pseudo likelihood fit, whose",
      "`vcov_type = \"%s\"` errors are not valid; use `vcov_type = \"robust\"`",
      "(the default for weighted fits) or `method = \"bootstrap\"`."), vcov_type),
      class = "latents_unsupported_weights", call = NULL))
  }
  vcov_type
}

.latents_is_weighted <- function(fit) {
  is.list(fit) && !is.null(fit$sampling_weights)
}

.latents_print_weights <- function(x) {
  if (!.latents_is_weighted(x)) return(invisible(NULL))
  weights <- x$sampling_weights
  cat(sprintf(paste("Sampling weights `%s` (pseudo maximum likelihood): Kish",
                    "effective n %.1f of %d units\n"),
              x$weights, sum(weights)^2 / sum(weights^2), length(weights)))
  invisible(NULL)
}

