.additive_block_names <- function(prefix, mode, class_names, vars) {
  if (identical(mode, "equal")) return(paste(prefix, vars, sep = "."))
  paste(prefix, rep(class_names, each = length(vars)), vars, sep = ".")
}

.additive_block_pack <- function(values, mode) {
  if (identical(mode, "equal")) values[1L, ] else as.vector(t(values))
}

.additive_block_unpack <- function(values, mode, n_classes, n_indicators) {
  rows <- .additive_rows(mode, n_classes)
  block <- matrix(values, rows, n_indicators, byrow = TRUE)
  block[rep(seq_len(rows), length.out = n_classes), , drop = FALSE]
}

.additive_block_combine <- function(pieces, mode) {
  if (identical(mode, "equal")) Reduce(`+`, pieces) else do.call(cbind, pieces)
}

.additive_block_labels <- function(mode, class_names, vars) {
  if (identical(mode, "equal")) {
    return(list(group_class = rep("shared", length(vars)), indicator = vars))
  }
  list(group_class = rep(class_names, each = length(vars)),
       indicator = rep(vars, length(class_names)))
}

.additive_tables <- function() {
  c("parameters", "group_classes", "groups", "intercepts",
    "conditional_intercepts", "assignments", "classification", "fit", "starts")
}

.additive_parameters_or_notice <- function(x, level, vcov_type, adjust) {
  refusals <- c("latents_boundary_fit", "latents_no_converge",
                "latents_singular_information", "latents_too_few_groups")
  inference <- tryCatch(.additive_inference(x, vcov_type),
    error = function(condition) {
      if (!inherits(condition, refusals)) stop(condition)
      .multilpa_notice(sprintf("No standard errors in this table: %s",
                               conditionMessage(condition)),
                       class = "latents_no_standard_errors")
      NULL
    })
  .additive_parameter_table(x, inference, level, adjust)
}

.additive_default_vcov <- function(x) {
  .latents_weighted_vcov(.latents_is_weighted(x), "observed", TRUE)
}

.additive_effective_or_na <- function(x) {
  refusals <- c("latents_boundary_fit", "latents_no_converge",
                "latents_singular_information", "latents_too_few_groups")
  inference <- tryCatch(
    withCallingHandlers(.additive_inference(x, .additive_default_vcov(x),
                                            warn_weak = FALSE),
                        latents_unconverged = function(w) {
                          invokeRestart("muffleWarning")
                        }),
    error = function(condition) {
      if (!inherits(condition, refusals)) stop(condition)
      NULL
    })
  if (is.null(inference)) return(rep(NA_real_, length(x$group_probabilities)))
  .additive_effective_groups(x, inference)$effective_groups
}

.additive_entropy <- function(posterior) {
  if (ncol(posterior) < 2L) return(NA_real_)
  terms <- ifelse(posterior > 0, posterior * log(posterior), 0)
  1 + sum(terms) / (nrow(posterior) * log(ncol(posterior)))
}

.additive_recovery <- function(x, data, truth) {
  if (is.null(data) || is.null(truth)) {
    stop(errorCondition("The `recovery` table needs `data` and `truth`.",
                        class = "latents_bad_argument", call = NULL))
  }
  if (!is.character(truth) || length(truth) != 1L || !truth %in% names(data)) {
    stop(errorCondition("`truth` must name one column of `data`.",
                        class = "latents_bad_argument", call = NULL))
  }
  supplied <- .additive_prepare(data, x$vars, x$id)
  if (!identical(supplied$ids, x$sufficient_statistics$ids) ||
      !identical(supplied$sizes, x$sufficient_statistics$sizes)) {
    stop(errorCondition("`data` does not have the groups this fit was made from.",
                        class = "latents_bad_inference_data", call = NULL))
  }
  values <- data[[truth]]
  per_group <- tapply(as.character(values), supplied$index,
                      function(v) length(unique(v)))
  if (anyNA(values) || any(per_group != 1L)) {
    stop(errorCondition(sprintf(
      "`%s` must be complete and constant within each group: group classes are group-level.",
      truth), class = "latents_bad_data", call = NULL))
  }
  group_truth <- as.character(values)[match(seq_len(supplied$n_groups),
                                            supplied$index)]
  assigned <- names(x$group_probabilities)[x$group_assignments]
  counts <- as.data.frame(table(assigned = assigned, truth = group_truth),
                          stringsAsFactors = FALSE, responseName = "n")
  counts$share <- counts$n / as.vector(table(assigned)[counts$assigned])
  counts <- counts[order(counts$assigned, counts$truth), , drop = FALSE]
  rownames(counts) <- NULL
  counts
}

get_results.multilpa_additive <- function(x, what = "parameters", level = 0.95,
                                          vcov_type = c("observed", "robust", "opg"),
                                          adjust = .multilpa_p_adjust_methods,
                                          data = NULL, truth = NULL, ...) {
  what <- match.arg(what, c(.additive_tables(), "recovery", "all"))
  vcov_type <- .latents_weighted_vcov(.latents_is_weighted(x), match.arg(vcov_type),
                                      missing(vcov_type))
  adjust <- match.arg(adjust)
  stopifnot("`level` must be a single number in (0, 1)" =
              is.numeric(level) && length(level) == 1L && level > 0 &&
              level < 1)
  if (identical(what, "all")) {
    return(stats::setNames(lapply(.additive_tables(), function(name) {
      .additive_table(x, name, level, vcov_type, adjust)
    }), .additive_tables()))
  }
  .additive_table(x, what, level, vcov_type, adjust, data, truth)
}

as.data.frame.multilpa_additive <- function(x, row.names = NULL, optional = FALSE,
                                            what = "parameters", ...) {
  get_results.multilpa_additive(x, what = what, ...)
}

logLik.multilpa_additive <- function(object, ...) {
  structure(object$log_likelihood, df = object$n_parameters,
            nobs = object$n_groups, class = "logLik")
}

summary.multilpa_additive <- function(object, level = 0.95,
                                      vcov_type = c("observed", "robust", "opg"),
                                      ...) {
  vcov_type <- .latents_weighted_vcov(.latents_is_weighted(object),
                                      match.arg(vcov_type), missing(vcov_type))
  tables <- c("fit", "parameters", "group_classes")
  structure(stats::setNames(lapply(tables, function(name) {
    .additive_table(object, name, level, vcov_type)
  }), tables), class = "summary_multilpa_additive")
}

print.summary_multilpa_additive <- function(x, digits = 4L, ...) {
  headings <- c(fit = "Model fit", parameters = "Parameters",
                group_classes = "Group classes")
  invisible(lapply(names(x), function(name) {
    cat(headings[[name]], "\n", sep = "")
    print(x[[name]], digits = digits, row.names = FALSE)
    cat("\n")
  }))
  cat("Every table: get_results(x, what = ), e.g. \"groups\", \"intercepts\", \"starts\".\n")
  invisible(x)
}

as.data.frame.summary_multilpa_additive <- function(x, row.names = NULL,
                                                    optional = FALSE, ...) {
  x$parameters
}

.additive_prepare <- function(data, vars, id, weights = NULL) {
  if (!is.data.frame(data) || !is.character(vars) || !is.character(id) ||
      nrow(data) < 2L || length(vars) < 1L || anyNA(vars) ||
      anyDuplicated(vars) || anyDuplicated(names(data)) ||
      length(id) != 1L || is.na(id) || id %in% vars ||
      !all(c(vars, id) %in% names(data))) {
    stop(errorCondition(
      "Supply a data frame with at least two rows, unique existing indicators, and one distinct group column.",
      class = "latents_bad_data", call = NULL))
  }
  frame <- data[, vars, drop = FALSE]
  if (!all(vapply(frame, is.numeric, logical(1))) ||
      any(vapply(frame, function(value) !is.null(dim(value)), logical(1)))) {
    stop(errorCondition(
      "Every indicator must be a numeric vector; the additive model takes continuous ratings.",
      class = "latents_bad_data", call = NULL))
  }
  x <- matrix(as.numeric(as.matrix(frame)), nrow = nrow(data),
              ncol = length(vars), dimnames = list(NULL, vars))
  if (!all(is.finite(x))) {
    stop(errorCondition(
      "Indicators contain missing or non-finite values; the additive model requires complete ratings.",
      class = "latents_bad_data", call = NULL))
  }
  if (any(vapply(seq_along(vars), function(r) {
    length(unique(x[, r])) < 2L
  }, logical(1)))) {
    stop(errorCondition("Constant indicators cannot identify group intercepts.",
                        class = "latents_bad_data", call = NULL))
  }
  groups <- .multilpa_prepare_groups(data[[id]])
  if (all(groups$sizes == 1L)) {
    stop(errorCondition(paste(
      "Every group has one observation, so within- and between-group variances",
      "are observed only through their sum. Supply groups with repeated ratings."),
      class = "latents_unidentified", call = NULL))
  }
  sizes <- groups$sizes
  averages <- rowsum(x, groups$index, reorder = TRUE) / sizes
  scatter <- rowsum((x - averages[groups$index, , drop = FALSE])^2,
                    groups$index, reorder = TRUE)
  dimnames(averages) <- dimnames(scatter) <- list(groups$ids, vars)
  stopifnot(
    "one sufficient-statistic row per group" =
      nrow(averages) == groups$n && nrow(scatter) == groups$n,
    "scatter must be nonnegative and finite" =
      all(is.finite(scatter)) && all(scatter >= 0),
    "group sizes must sum to the number of rows" = sum(sizes) == nrow(data)
  )
  # Sampling weights, one per group, travel with the statistics: every
  # posterior-weighted sum the M-step and the scores form is weighted by them.
  sampling_weights <- .latents_sampling_weights(data, weights, groups$index, groups$n)
  structure(list(
    ids = groups$ids, index = groups$index, sizes = sizes,
    n_groups = groups$n, n_obs = nrow(data), vars = vars,
    averages = averages, scatter = scatter,
    pooled_scatter = colSums(scatter),
    sampling_weights = sampling_weights,
    weighted_n_obs = if (is.null(sampling_weights)) NULL else
      sum(sampling_weights * sizes)
  ), class = "latents_additive_data")
}

.additive_row <- function(values, h, n_groups) {
  matrix(values[h, ], n_groups, ncol(values), byrow = TRUE)
}

.additive_slice <- function(values, h) {
  matrix(values[, , h], nrow = dim(values)[1L], ncol = dim(values)[2L])
}

.additive_pool <- function(values, weight, mode) {
  if (identical(mode, "varying")) return(values)
  pooled <- colSums(values * weight) / colSums(weight)
  matrix(pooled, nrow(values), ncol(values), byrow = TRUE)
}

.additive_initialize <- function(stats, n_classes, structure, min_variance,
                                 start_index, kind = "kmeans") {
  standardize <- function(values) {
    spread <- apply(values, 2L, stats::sd)
    spread[!is.finite(spread) | spread <= 0] <- 1
    sweep(sweep(values, 2L, colMeans(values)), 2L, spread, "/")
  }
  # Log within-group variance per group; a singleton group, which has none,
  # takes the indicator's average over the replicated groups.
  replicated <- stats$sizes > 1L
  log_spread <- log(pmax(stats$scatter / pmax(stats$sizes - 1, 1),
                         min_variance))
  if (any(!replicated)) {
    fill <- colMeans(log_spread[replicated, , drop = FALSE])
    log_spread[!replicated, ] <- matrix(fill, sum(!replicated), ncol(log_spread),
                                        byrow = TRUE)
  }
  features <- cbind(
    if (identical(structure$means, "varying")) standardize(stats$averages),
    if (identical(structure$within, "varying")) standardize(log_spread))
  hard <- if (n_classes == 1L) {
    rep(1L, stats$n_groups)
  } else if (start_index == 1L) {
    .multilpa_ward_assignments(features, n_classes)
  } else if (identical(kind, "partition")) {
    # An emEM pool start: the groups dealt into the classes at random.
    sample(rep_len(seq_len(n_classes), stats$n_groups))
  } else {
    centres <- features[sample.int(stats$n_groups, n_classes), , drop = FALSE]
    distance <- vapply(seq_len(n_classes), function(h) {
      colSums((t(features) - centres[h, ])^2)
    }, numeric(stats$n_groups))
    max.col(-matrix(distance, stats$n_groups), ties.method = "first")
  }
  posterior <- 0.9 * outer(hard, seq_len(n_classes), "==") + 0.1 / n_classes
  counts <- colSums(posterior)
  n_indicators <- length(stats$vars)
  class_weight <- matrix(counts, n_classes, n_indicators)
  means <- .additive_pool(crossprod(posterior, stats$averages) / counts,
                          class_weight, structure$means)
  pooled_within <- pmax(stats$pooled_scatter / (stats$n_obs - stats$n_groups),
                        min_variance)
  within <- if (identical(structure$within, "varying")) {
    degrees <- colSums(posterior * pmax(stats$sizes - 1, 0))
    class_within <- crossprod(posterior, stats$scatter) / pmax(degrees, 1)
    usable <- degrees > 0
    if (any(!usable)) {
      class_within[!usable, ] <- matrix(pooled_within, sum(!usable),
                                        n_indicators, byrow = TRUE)
    }
    pmax(class_within, min_variance)
  } else {
    matrix(pooled_within, n_classes, n_indicators, byrow = TRUE)
  }
  floor <- pmax(0.01 * apply(stats$averages, 2L, stats::var), min_variance)
  floor[!is.finite(floor)] <- min_variance
  raw <- matrix(vapply(seq_len(n_classes), function(h) {
    mean_size <- sum(posterior[, h] * stats$sizes) / counts[h]
    colSums(posterior[, h] * sweep(stats$averages, 2L, means[h, ])^2) /
      counts[h] - within[h, ] / mean_size
  }, numeric(n_indicators)), nrow = n_classes, byrow = TRUE)
  between <- pmax(.additive_pool(raw, class_weight, structure$between),
                  matrix(floor, n_classes, n_indicators, byrow = TRUE))
  list(means = unname(means), between = unname(between),
       within = unname(within), weights = unname(counts / stats$n_groups))
}

.additive_accelerator <- function(zero) {
  blocks <- c("means", "between", "within", "weights")
  list(
    flatten = function(parameters) unlist(parameters[blocks], use.names = FALSE),
    restore = function(template, values) {
      sizes <- lengths(template[blocks])
      ends <- cumsum(sizes)
      template[blocks] <- lapply(seq_along(blocks), function(k) {
        block <- template[[blocks[k]]]
        block[] <- values[seq.int(ends[k] - sizes[k] + 1L, length.out = sizes[k])]
        block
      })
      template
    },
    valid = function(parameters) {
      values <- unlist(parameters[blocks], use.names = FALSE)
      all(is.finite(values)) && all(parameters$within > 0) &&
        all(parameters$weights > 0) && all(parameters$between[!zero] > 0) &&
        all(parameters$between[zero] == 0)
    })
}

.additive_polish <- function(stats, fit, structure, min_variance, max_iter, tol) {
  n_classes <- nrow(fit$parameters$means)
  n_indicators <- length(stats$vars)
  none <- matrix(FALSE, n_classes, n_indicators)
  interior <- c(fit, list(zero = none, kkt = TRUE))
  # One coordinate per class and indicator ("varying") or per indicator
  # ("equal"): zero it alone and read the derivative there.
  coordinates <- if (identical(structure$between, "equal")) {
    lapply(seq_len(n_indicators), function(r) {
      mask <- none
      mask[, r] <- TRUE
      mask
    })
  } else {
    lapply(seq_len(n_classes * n_indicators), function(k) {
      mask <- none
      mask[k] <- TRUE
      mask
    })
  }
  score_at_zero <- vapply(coordinates, function(mask) {
    point <- fit$parameters
    point$between[mask] <- 0
    posterior <- .additive_expectation(stats, point)$posterior
    sum(.additive_between_score(stats, point, posterior, "varying")[mask])
  }, numeric(1))
  candidates <- Reduce(`|`, coordinates[score_at_zero <= 0], none)
  if (!any(candidates)) return(interior)
  slack <- sqrt(.Machine$double.eps) * (1 + abs(fit$expectation$log_likelihood))
  refit <- function(mask, point) {
    point$between[mask] <- 0
    c(.additive_em(stats, point, structure, min_variance, max_iter, tol, mask),
      list(zero = mask))
  }
  boundary <- refit(candidates, fit$parameters)
  rounds <- 1L
  # Releasing coordinates shrinks the held set, so this ends within
  # length(coordinates) rounds.
  repeat {
    score <- .additive_between_score(stats, boundary$parameters,
                                     boundary$expectation$posterior, "varying")
    held_scores <- vapply(coordinates, function(mask) {
      if (all(boundary$zero[mask])) sum(score[mask]) else -Inf
    }, numeric(1))
    release <- held_scores > slack
    if (!any(release) || rounds > length(coordinates)) break
    mask <- boundary$zero & !Reduce(`|`, coordinates[release], none)
    point <- boundary$parameters
    released <- boundary$zero & !mask
    point$between[released] <- pmax(0.01 * point$within, min_variance)[released]
    boundary <- refit(mask, point)
    rounds <- rounds + 1L
  }
  boundary$kkt <- !any(release)
  boundary$iterations <- fit$iterations + boundary$iterations
  boundary$history <- c(fit$history, boundary$history)
  better <- boundary$expectation$log_likelihood >=
    fit$expectation$log_likelihood - tol * (1 + abs(fit$expectation$log_likelihood))
  if (isTRUE(boundary$kkt) && better && any(boundary$zero)) boundary else interior
}

.additive_arguments <- function() {
  c("data", "vars", "id", "n_group_classes", "family", "between_variance",
    "n_starts", "max_iter", "tol", "min_variance", "seed", "weights",
    "search", "n_screen")
}

.additive_rows <- function(mode, n_classes) {
  if (identical(mode, "equal")) 1L else n_classes
}

.additive_count_parameters <- function(n_classes, n_indicators, structure) {
  as.integer(n_indicators * (.additive_rows(structure$means, n_classes) +
                               .additive_rows(structure$between, n_classes) +
                               .additive_rows(structure$within, n_classes)) +
               n_classes - 1L)
}

.additive_family_label <- function(family) {
  switch(family, additive = "Additive", dispersion = "Dispersion",
         additive_dispersion = "Additive-dispersion")
}

.multilpa_refit_measurement <- function(x) {
  extensions <- list(direct_effects = if (is.null(x$extra_data$direct)) character() else
    .latents_direct_terms(x$extra_data$direct$effects))
  if (!is.null(x$covariance_pattern)) {
    return(c(list(variance_model = x$variance_model,
                  local_dependence = .latents_pattern_pairs(x$covariance_pattern)),
             extensions))
  }
  structure <- x$covariance_structure
  family <- if (is.null(structure) || is.na(structure) ||
                !structure %in% .multilpa_structures()) {
    list(variance_model = x$variance_model,
         covariance_model = x$covariance_model %||% "diagonal")
  } else .multilpa_structure_arguments(structure)
  c(family, extensions)
}

.multilpa_cov_encode <- function(object) {
  variances <- if (identical(object$variance_model, "equal")) {
    object$variances[1L, , drop = FALSE]
  } else object$variances
  ## The fit reports means in input units; the likelihood is evaluated on
  ## centred indicators, so the centre comes off here and goes back on in the
  ## reported estimates. A location shift leaves the standard errors alone.
  centred_means <- if (ncol(object$means) > 0L) {
    sweep(object$means, 2L, object$center, "-")
  } else object$means
  spread <- if (.multilpa_cov_is_full(object)) {
    .multilpa_cov_cholesky_coordinates(object)
  } else as.vector(t(log(variances)))
  ## Response probabilities as multinomial logits against each indicator's last
  ## category: the coordinates the covariate-free model is estimated on.
  response <- unname(.multilpa_response_coordinates(object, "unconstrained"))
  extra <- unname(.latents_extra_coordinates(object, object$extra_data,
                                             object$n_profiles, "unconstrained"))
  c(as.vector(t(centred_means)), spread, response, extra,
    as.vector(object$profile_coefficients), as.vector(object$group_coefficients))
}

.multilpa_cov_is_full <- function(object) {
  identical(object$covariance_model %||% "diagonal", "full")
}

.multilpa_cov_spread_rows <- function(object) {
  if (identical(object$variance_model, "equal")) 1L else seq_len(object$n_profiles)
}

.multilpa_cov_cholesky_coordinates <- function(object) {
  dimension <- ncol(object$means)
  lower <- lower.tri(matrix(0, dimension, dimension), diag = TRUE)
  unlist(lapply(.multilpa_cov_spread_rows(object), function(profile) {
    factor <- t(chol(matrix(object$covariances[, , profile], dimension, dimension)))
    diag(factor) <- log(diag(factor))
    factor[lower]
  }), use.names = FALSE)
}

.multilpa_cov_cholesky_decode <- function(values, dimension, n_profiles, shared) {
  lower <- lower.tri(matrix(0, dimension, dimension), diag = TRUE)
  width <- sum(lower)
  blocks <- lapply(seq_len(if (shared) 1L else n_profiles), function(index) {
    factor <- matrix(0, dimension, dimension)
    factor[lower] <- values[(index - 1L) * width + seq_len(width)]
    diag(factor) <- exp(diag(factor))
    tcrossprod(factor)
  })
  if (shared) blocks <- rep(blocks, n_profiles)
  array(unlist(blocks, use.names = FALSE), c(dimension, dimension, n_profiles))
}

.multilpa_cov_decode <- function(theta, object) {
  n_profiles <- object$n_profiles
  n_indicators <- length(.multilpa_continuous_names(object))
  n_variance_rows <- if (identical(object$variance_model, "equal")) 1L else n_profiles
  at <- 0L
  take <- function(n) {
    values <- theta[at + seq_len(n)]
    at <<- at + n
    values
  }
  means <- matrix(take(n_profiles * n_indicators), n_profiles, n_indicators,
                  byrow = TRUE)
  covariances <- NULL
  if (.multilpa_cov_is_full(object)) {
    width <- n_indicators * (n_indicators + 1L) / 2L
    covariances <- .multilpa_cov_cholesky_decode(
      take(length(.multilpa_cov_spread_rows(object)) * width), n_indicators,
      n_profiles, n_variance_rows == 1L)
    variances <- t(matrix(vapply(seq_len(n_profiles), function(profile) {
      diag(matrix(covariances[, , profile], n_indicators, n_indicators))
    }, numeric(n_indicators)), n_indicators, n_profiles))
  } else {
    variances <- exp(matrix(take(n_variance_rows * n_indicators), n_variance_rows,
                            n_indicators, byrow = TRUE))
    if (n_variance_rows == 1L) {
      variances <- matrix(variances, n_profiles, n_indicators, byrow = TRUE)
    }
  }
  response_width <- .multilpa_response_width(object)
  response_probabilities <- if (response_width > 0L) {
    .multilpa_response_decode(take(response_width), object)
  } else NULL
  extra_width <- .latents_extra_width(object$extra_data, n_profiles)
  extra_blocks <- if (extra_width > 0L) {
    .latents_extra_decode(take(extra_width), object$extra_data, n_profiles)
  } else NULL
  beta <- matrix(take(length(object$profile_coefficients)),
                 nrow(object$profile_coefficients), ncol(object$profile_coefficients))
  gamma <- matrix(take(length(object$group_coefficients)),
                  nrow(object$group_coefficients), ncol(object$group_coefficients))
  parameters <- list(means = means, variances = variances)
  if (!is.null(covariances)) parameters$covariances <- covariances
  if (!is.null(response_probabilities)) {
    parameters$response_probabilities <- response_probabilities
  }
  if (!is.null(extra_blocks)) parameters[names(extra_blocks)] <- extra_blocks
  list(parameters = parameters, beta = beta, gamma = gamma)
}

.multilpa_cov_estimation_labels <- function(object) {
  labels <- .multilpa_cov_labels(object, response = "free")
  on_diagonal <- vapply(strsplit(labels$term, ":", fixed = TRUE), function(pair) {
    length(pair) == 2L && identical(pair[[1L]], pair[[2L]])
  }, logical(1))
  labels$parameter <- ifelse(
    labels$parameter == "variance", "log_variance",
    ifelse(labels$parameter == "covariance",
           ifelse(on_diagonal, "log_cholesky", "cholesky"), labels$parameter))
  labels
}

.multilpa_cov_front_estimate <- function(object, theta, labels) {
  estimate <- theta
  is_mean <- labels$parameter == "mean"
  is_variance <- labels$parameter == "variance"
  is_covariance <- labels$parameter == "covariance"
  estimate[is_mean] <- estimate[is_mean] +
    rep(object$center, times = object$n_profiles)
  estimate[is_variance] <- exp(theta[is_variance])
  if (any(is_covariance)) {
    dimension <- length(.multilpa_continuous_names(object))
    width <- dimension * (dimension + 1L) / 2L
    starts <- which(is_covariance)[seq(1L, sum(is_covariance), by = width)]
    estimate[is_covariance] <- unlist(lapply(starts, function(first) {
      .multilpa_cov_cholesky_natural(theta[first + seq_len(width) - 1L], dimension)
    }), use.names = FALSE)
  }
  estimate
}

.multilpa_cov_front_jacobian <- function(object, theta, labels) {
  jacobian <- diag(1, length(theta))
  is_variance <- labels$parameter == "variance"
  is_covariance <- labels$parameter == "covariance"
  diag(jacobian)[is_variance] <- exp(theta[is_variance])
  if (any(is_covariance)) {
    dimension <- length(.multilpa_continuous_names(object))
    width <- dimension * (dimension + 1L) / 2L
    starts <- which(is_covariance)[seq(1L, sum(is_covariance), by = width)]
    invisible(lapply(starts, function(first) {
      at <- first + seq_len(width) - 1L
      jacobian[at, at] <<- .multilpa_cov_cholesky_jacobian(theta[at], dimension)
    }))
  }
  jacobian
}

.multilpa_cov_natural_estimate <- function(object, theta, labels) {
  at <- .multilpa_cov_blocks(object, length(theta))
  front_labels <- labels[at$front, , drop = FALSE]
  response <- if (length(at$response) > 0L) {
    unlist(lapply(.multilpa_response_decode(theta[at$response], object),
                  function(block) as.vector(t(block))), use.names = FALSE)
  } else numeric(0)
  extra <- if (length(at$extra) > 0L) {
    unname(.latents_extra_coordinates(
      .latents_extra_decode(theta[at$extra], object$extra_data, object$n_profiles),
      object$extra_data, object$n_profiles, "natural"))
  } else numeric(0)
  estimate <- c(.multilpa_cov_front_estimate(object, theta[at$front], front_labels),
                response, extra, theta[at$back])
  stopifnot("every natural parameter must be labelled" =
              length(estimate) == nrow(labels))
  estimate
}

.multilpa_cov_cholesky_jacobian <- function(values, dimension) {
  step <- 1e-6
  columns <- lapply(seq_along(values), function(index) {
    up <- values; down <- values
    up[index] <- up[index] + step
    down[index] <- down[index] - step
    (.multilpa_cov_cholesky_natural(up, dimension) -
       .multilpa_cov_cholesky_natural(down, dimension)) / (2 * step)
  })
  matrix(unlist(columns, use.names = FALSE), length(values), length(values))
}

coef.multilpa_covariates <- function(object, scale = c("natural", "unconstrained"),
                                     ...) {
  stopifnot("`object` must be a fitted `multilpa_covariates` model" =
              inherits(object, "multilpa_covariates"))
  scale <- match.arg(scale)
  theta <- .multilpa_cov_encode(object)
  if (identical(scale, "unconstrained")) {
    return(stats::setNames(
      theta, .multilpa_parameter_names(.multilpa_cov_estimation_labels(object))))
  }
  ## Means are stored centred for the likelihood and reported in input units;
  ## the spread block is estimated as logs or log-Cholesky coordinates and comes
  ## back through the same map [parameter_inference()] reports it through, so
  ## the two can never disagree.
  stats::setNames(
    .multilpa_cov_natural_estimate(object, theta, .multilpa_cov_labels(object)),
    .multilpa_cov_parameter_names(object))
}

confint.multilpa_covariates <- function(object, parm, level = 0.95, data = NULL,
                                        ...) {
  stopifnot("`object` must be a fitted `multilpa_covariates` model" =
              inherits(object, "multilpa_covariates"),
            "`data` must be a data frame when supplied" =
              is.null(data) || is.data.frame(data))
  inference <- parameter_inference(object, data, level = level, ...)
  names_all <- .multilpa_cov_parameter_names(object)
  intervals <- cbind(inference$conf_low, inference$conf_high)
  dimnames(intervals) <- list(names_all, paste0(
    format(100 * c((1 - level) / 2, (1 + level) / 2), trim = TRUE), "%"))
  if (missing(parm)) return(intervals)
  ## The class confint.multilpa() raises for the same mistake.
  bad_parm <- function() {
    stop(errorCondition(
      "`parm` must identify existing parameters by name or index.",
      class = "latents_bad_argument", call = NULL))
  }
  if (is.numeric(parm)) {
    if (anyNA(parm) || any(parm < 1) || any(parm > length(names_all)) ||
        any(parm != floor(parm))) {
      bad_parm()
    }
    parm <- names_all[parm]
  }
  if (!is.character(parm) || anyNA(parm) || !all(parm %in% names_all)) {
    bad_parm()
  }
  intervals[parm, , drop = FALSE]
}

.growth_names <- function(spec) {
  classes <- paste0("class_", seq_len(spec$n_classes))
  random_names <- colnames(spec$random_design)
  n_random <- length(random_names)
  cholesky <- function(owner) {
    diagonal <- sprintf("random.log_cholesky.%s.%s:%s", owner, random_names, random_names)
    if (isTRUE(spec$random_diagonal) || n_random == 1L) return(diagonal)
    pairs <- which(lower.tri(diag(n_random)), arr.ind = TRUE)
    c(diagonal, sprintf("random.cholesky.%s.%s:%s", owner,
                        random_names[pairs[, 1L]], random_names[pairs[, 2L]]))
  }
  matrices <- switch(spec$random_covariance, varying = classes, "shared")
  c(as.vector(outer(colnames(spec$x), classes,
                    function(term, class) sprintf("coefficient.%s.%s", class, term))),
    if (ncol(spec$z) > 0L) sprintf("coefficient.common.%s", colnames(spec$z)),
    if (identical(spec$variance, "equal")) "log_sigma.shared" else
      sprintf("log_sigma.%s", classes),
    unlist(lapply(matrices, cholesky)),
    if (identical(spec$random_covariance, "proportional"))
      sprintf("random.log_scale.%s", classes[-spec$n_classes]),
    .growth_correlation_names(spec),
    .growth_structure_names(.growth_structure(spec)))
}

.growth_pack <- function(spec, params) {
  n_random <- ncol(spec$random_design)
  chart <- function(covariance) {
    factor <- .growth_factor(covariance)
    diagonal <- log(diag(factor))
    if (isTRUE(spec$random_diagonal) || n_random == 1L) return(diagonal)
    c(diagonal, factor[lower.tri(factor)])
  }
  sigma <- 0.5 * log(params$sigma2)
  theta <- c(as.vector(params$beta), params$common,
             if (identical(spec$variance, "equal")) sigma[1L] else sigma,
             unlist(lapply(params$random_covariance, chart)),
             if (identical(spec$random_covariance, "proportional"))
               log(params$random_scale[-spec$n_classes]),
             if (.growth_is_correlated(spec)) log(params$correlation),
             .mixture_structure_pack(.growth_structure(spec), params))
  stats::setNames(theta, .growth_names(spec))
}

.growth_scores <- function(spec, stats, params, expectation = NULL) {
  expectation <- expectation %||% .growth_expectation(spec, stats, params)
  if (.growth_is_correlated(spec)) {
    return(.growth_dense_scores(spec, stats, params, expectation))
  }
  n_classes <- spec$n_classes
  n_specific <- ncol(spec$x)
  n_common <- ncol(spec$z)
  n_columns <- n_specific + n_common
  n_random <- ncol(spec$random_design)
  n_persons <- length(stats$n)
  posterior <- expectation$posterior
  covariances <- .growth_covariances(spec, params)
  zz_flat <- matrix(stats$zz, n_random^2, n_persons)
  # Per class: derivatives of log f_k for every person.
  per_class <- lapply(seq_len(n_classes), function(k) {
    sigma2 <- params$sigma2[k]
    coefficients <- .growth_coefficients(params, k)
    residuals <- .growth_residuals(stats, coefficients)
    means <- expectation$means[[k]]
    pattern_covariance <- matrix(expectation$covariances[[k]], n_random^2)[, stats$pattern,
                                                                        drop = FALSE]
    # X'r = X'y - X'X beta, X'Z m and Z'Z m, persons by columns.
    by_column <- function(array3, rows, vector_or_matrix) {
      Reduce(`+`, lapply(seq_along(rows), function(b) {
        slice <- matrix(array3[, b, ], dim(array3)[1L], n_persons)
        weight <- if (is.matrix(vector_or_matrix)) vector_or_matrix[, b] else
          vector_or_matrix[b]
        t(slice) * weight
      }))
    }
    xr <- stats$xy - by_column(stats$xx, seq_len(n_columns), coefficients)
    if (length(residuals$direct) && !is.null(stats$raw)) {
      # X'r of the fixed-effects residual: the direct form with zero
      # random-effect means.
      xr[residuals$direct, ] <- .growth_direct_residuals(
        stats, coefficients, matrix(0, n_persons, n_random), residuals$direct)$xr
    }
    xzm <- by_column(stats$xz, seq_len(n_random), means)
    zzm <- by_column(stats$zz, seq_len(n_random), means)
    d_beta <- (xr - xzm) / sigma2
    residual_ss <- residuals$rr - 2 * rowSums(means * residuals$zr) + rowSums(means * zzm)
    unstable <- which(residual_ss <= 1e-6 * (abs(residuals$rr) +
      2 * abs(rowSums(means * residuals$zr)) + abs(rowSums(means * zzm))))
    direct <- if (length(unstable) && !is.null(stats$raw)) {
      .growth_direct_residuals(stats, coefficients, means, unstable)
    } else NULL
    if (!is.null(direct)) {
      residual_ss[unstable] <- direct$rr
      d_beta[unstable, ] <- direct$xr / sigma2
    }
    trace_term <- colSums(zz_flat * pattern_covariance)
    d_sigma2 <- (residual_ss / sigma2 - stats$n + trace_term / sigma2) / (2 * sigma2)
    # q = Z'V^-1 r = (Z'r - Z'Z m) / sigma^2; Z'V^-1 Z depends on the pattern only.
    q <- (residuals$zr - zzm) / sigma2
    if (!is.null(direct)) q[unstable, ] <- direct$zr / sigma2
    zvz <- vapply(seq_len(dim(stats$pattern_zz)[3L]), function(g) {
      zz <- matrix(stats$pattern_zz[, , g], n_random)
      s <- matrix(expectation$covariances[[k]][, , g], n_random)
      factor <- .growth_factor(covariances[[k]])
      kernel <- crossprod(factor, zz %*% factor) / sigma2
      if (max(abs(kernel)) > 1e6) {
        # At a large random/residual variance ratio the Woodbury difference
        # also loses precision in Z'V^-1 Z and Z'V^-1 r. Work in the random
        # space, where I - A^-1 stays away from catastrophic cancellation.
        inverse_factor <- forwardsolve(factor, diag(n_random))
        a_inverse <- chol2inv(chol(diag(n_random) + kernel))
        members <- which(stats$pattern == g)
        stable_q <- (residuals$zr[members, , drop = FALSE] %*%
          factor %*% a_inverse / sigma2) %*% inverse_factor
        if (!is.null(stats$raw)) {
          # Decompose the fixed design into its random-design projection and
          # orthogonal residual. Replace the cancellation-prone projected
          # score by B' (Z'V^-1 r), retaining the directly computed residual.
          difference <- stable_q - q[members, , drop = FALSE]
          invisible(lapply(seq_along(members), function(at) {
            i <- members[at]
            rows <- stats$raw$rows[[i]]
            projection <- qr.coef(qr(stats$raw$random[rows, , drop = FALSE]),
                                  stats$raw$design[rows, , drop = FALSE])
            projection[is.na(projection)] <- 0
            d_beta[i, ] <<- d_beta[i, ] +
              as.vector(crossprod(projection, difference[at, ]))
          }))
        }
        q[members, ] <<- stable_q
        return(as.vector(crossprod(inverse_factor,
          (diag(n_random) - a_inverse) %*% inverse_factor)))
      }
      as.vector((zz - zz %*% s %*% zz / sigma2) / sigma2)
    }, numeric(n_random^2)) |> matrix(n_random^2)
    outer_q <- t(q[, rep(seq_len(n_random), n_random), drop = FALSE] *
                   q[, rep(seq_len(n_random), each = n_random), drop = FALSE])
    d_g <- (outer_q - zvz[, stats$pattern, drop = FALSE]) / 2
    list(beta = d_beta, sigma2 = d_sigma2, g = d_g, covariance = covariances[[k]])
  })
  # Coefficients.
  beta_scores <- do.call(cbind, lapply(seq_len(n_classes), function(k) {
    per_class[[k]]$beta[, seq_len(n_specific), drop = FALSE] * posterior[, k]
  }))
  common_scores <- if (n_common > 0L) {
    Reduce(`+`, lapply(seq_len(n_classes), function(k) {
      per_class[[k]]$beta[, n_specific + seq_len(n_common), drop = FALSE] * posterior[, k]
    }))
  }
  # log sigma: d/d log sigma = 2 sigma^2 d/d sigma^2.
  sigma_by_class <- vapply(seq_len(n_classes), function(k) {
    2 * params$sigma2[k] * per_class[[k]]$sigma2 * posterior[, k]
  }, numeric(n_persons)) |> matrix(n_persons, n_classes)
  sigma_scores <- if (identical(spec$variance, "equal")) {
    matrix(rowSums(sigma_by_class), n_persons, 1L)
  } else sigma_by_class
  # Random-effect covariance, through its chart.
  chart_scores <- function(d_g_flat, covariance) {
    factor <- .growth_factor(covariance)
    t(apply(d_g_flat, 2L, function(column) {
      d <- matrix(column, n_random)
      d <- (d + t(d)) / 2
      d_factor <- 2 * d %*% factor
      diagonal <- diag(d_factor) * diag(factor)
      if (isTRUE(spec$random_diagonal) || n_random == 1L) return(diagonal)
      c(diagonal, d_factor[lower.tri(d_factor)])
    })) |> matrix(n_persons)
  }
  class_g <- lapply(seq_len(n_classes), function(k) {
    per_class[[k]]$g * rep(posterior[, k], each = n_random^2)
  })
  random_scores <- switch(spec$random_covariance,
    varying = do.call(cbind, lapply(seq_len(n_classes), function(k) {
      chart_scores(class_g[[k]], covariances[[k]])
    })),
    equal = chart_scores(Reduce(`+`, class_g), covariances[[1L]]),
    proportional = {
      shared <- params$random_covariance[[1L]]
      scale2 <- params$random_scale^2
      base <- chart_scores(Reduce(`+`, Map(`*`, class_g, scale2)), shared)
      scale_scores <- vapply(seq_len(n_classes - 1L), function(k) {
        2 * colSums(class_g[[k]] * as.vector(covariances[[k]]))
      }, numeric(n_persons)) |> matrix(n_persons)
      cbind(base, scale_scores)
    })
  block <- cbind(beta_scores, common_scores, sigma_scores, random_scores)
  scores <- if (is.null(spec$cluster)) {
    # Membership logits of classes 2..K.
    prior <- exp(.mixture_log_softmax(spec$w, params$gamma))
    membership_scores <- if (n_classes > 1L) {
      do.call(cbind, lapply(seq_len(n_classes)[-1L], function(k) {
        spec$w * (posterior[, k] - prior[, k])
      }))
    }
    cbind(block, membership_scores)
  } else {
    # The clusters are the independent units: each person's block scores
    # (already weighted by their posteriors given the whole cluster) add up
    # within the cluster, beside the cluster's membership scores.
    cbind(rowsum(block, spec$cluster_index, reorder = TRUE),
          .mixture_structure_scores(.growth_structure(spec), expectation$structure))
  }
  dimnames(scores) <- list(NULL, .growth_names(spec))
  scores
}

.growth_quasi_newton <- function(spec, stats, params, tol) {
  theta <- .growth_pack(spec, params)
  names_all <- names(theta)
  lower <- rep(-Inf, length(theta))
  lower[startsWith(names_all, "log_sigma.")] <- 0.5 * log(spec$min_variance)
  lower[startsWith(names_all, "random.log_cholesky.")] <- 0.5 * log(spec$min_variance)
  weights <- spec$sampling_weights %||% 1
  value <- function(v) {
    -.growth_expectation(spec, stats, .growth_unpack(spec, v, params))$log_likelihood
  }
  gradient <- function(v) {
    current <- .growth_unpack(spec, v, params)
    -colSums(.growth_scores(spec, stats, current) * weights)
  }
  # Polished to near machine precision whatever `tol` is: with the analytic
  # gradient it is cheap, and `tol` judges convergence below.
  finish <- .latents_quasi_newton(theta, lower, value, gradient, tol,
                                  list(maxit = 2000L, factr = 10, pgtol = 0))
  if (!finish$improved) {
    return(list(params = params, converged = FALSE,
                log_likelihood = -finish$start_value))
  }
  list(params = .growth_unpack(spec, finish$par, params), converged = finish$converged,
       log_likelihood = -finish$value)
}

.growth_permute_params <- function(spec, params, order) {
  params$beta <- params$beta[, order, drop = FALSE]
  params$sigma2 <- params$sigma2[order]
  if (identical(spec$random_covariance, "varying")) {
    params$random_covariance <- params$random_covariance[order]
  }
  if (identical(spec$random_covariance, "proportional")) {
    params$random_scale <- params$random_scale[order]
  }
  params$gamma <- params$gamma[, order, drop = FALSE] -
    params$gamma[, order[1L]]
  params
}

.growth_align_refit <- function(x, refit) {
  order <- .growth_match_classes(x, refit)$order
  .growth_permute_params(refit$spec, refit$params, order)
}

.inference_score_information <- function(total_score, theta, step,
                                         scheme = c("central", "five_point"),
                                         h_rule = c("plus1", "max1", "absolute")) {
  scheme <- match.arg(scheme)
  h_rule <- match.arg(h_rule)
  width <- function(value) {
    switch(h_rule, plus1 = step * (1 + abs(value)),
           max1 = step * max(1, abs(value)), absolute = step)
  }
  if (identical(scheme, "central")) {
    columns <- lapply(seq_along(theta), function(j) {
      h <- width(theta[j])
      up <- theta
      down <- theta
      up[j] <- up[j] + h
      down[j] <- down[j] - h
      (total_score(up) - total_score(down)) / (2 * h)
    })
    hessian <- do.call(cbind, columns)
    information <- -(hessian + t(hessian)) / 2
  } else {
    columns <- vapply(seq_along(theta), function(k) {
      h <- width(theta[k])
      at <- function(multiple) {
        point <- theta
        point[k] <- point[k] + multiple * h
        total_score(point)
      }
      (-at(2) + 8 * at(1) - 8 * at(-1) + at(-2)) / (12 * h)
    }, numeric(length(theta)))
    information <- -(columns + t(columns)) / 2
  }
  dimnames(information) <- list(names(theta), names(theta))
  information
}

.inference_positive_definite <- function(information,
                                         rule = c("min_le_eps_max", "ratio_le_eps",
                                                  "min_le_eps_maxabs"),
                                         message = NULL) {
  rule <- match.arg(rule)
  eigenvalues <- eigen(information, symmetric = TRUE, only.values = TRUE)$values
  refuse <- function(text) {
    stop(errorCondition(text, class = "latents_singular_information", call = NULL))
  }
  switch(rule,
    min_le_eps_max = {
      if (!all(is.finite(eigenvalues)) ||
          min(eigenvalues) <= 1e-10 * max(eigenvalues)) {
        refuse(message %||% "The observed information is not positive definite.")
      }
      TRUE
    },
    ratio_le_eps = {
      condition_ratio <- min(eigenvalues) / max(eigenvalues)
      # A negative definite matrix has a positive ratio; its smallest
      # eigenvalue is what shows it.
      if (!is.finite(condition_ratio) || condition_ratio <= 1e-10 ||
          min(eigenvalues) <= 0) {
        refuse(sprintf(message %||% paste(
          "The observed information is not positive definite (eigenvalue",
          "ratio %.3g)."), condition_ratio))
      }
      TRUE
    },
    min_le_eps_maxabs = all(is.finite(eigenvalues)) &&
      min(eigenvalues) > 1e-10 * max(abs(eigenvalues)))
}

.inference_invert <- function(information, rule = "min_le_eps_max", message = NULL) {
  .inference_positive_definite(information, rule, message)
  chol2inv(chol(information))
}

.inference_require_rank <- function(scores, message, formatted = FALSE,
                                    extra = list()) {
  rank <- qr(scores)$rank
  if (rank < ncol(scores)) {
    text <- if (formatted) do.call(sprintf, c(list(message, nrow(scores), rank,
                                                    ncol(scores)), extra)) else message
    stop(errorCondition(text, class = "latents_too_few_groups", call = NULL))
  }
  invisible(NULL)
}

.multilpa_inference_groups <- function(object, observed_only = FALSE) {
  stopifnot(is.list(object), length(object$n_groups) == 1L,
            isTRUE(observed_only) || isFALSE(observed_only))
  selected <- rep(TRUE, object$n_groups)
  if ((observed_only || !isFALSE(object$drop_empty)) && !is.null(object$informative)) {
    selected[] <- FALSE
    selected[seq_len(object$n_groups) %in%
               object$group_index[object$informative]] <- TRUE
  }
  selected & (object$sampling_weights %||% rep(1, object$n_groups)) > 0
}

.inference_cluster_factor <- function(n_units) {
  stopifnot("`n_units` must be a single count of at least two units" =
              is.numeric(n_units) && length(n_units) == 1L && n_units >= 2)
  n_units / (n_units - 1)
}

.inference_sandwich <- function(bread, meat, n_units) {
  bread %*% (meat * .inference_cluster_factor(n_units)) %*% bread
}

.inference_delta_covariance <- function(jacobian, covariance) {
  jacobian %*% covariance %*% t(jacobian)
}

.inference_numeric_jacobian <- function(transform, theta, step = 1e-6) {
  estimate <- transform(theta)
  jacobian <- do.call(cbind, lapply(seq_along(theta), function(j) {
    h <- step * (1 + abs(theta[j]))
    up <- theta
    down <- theta
    up[j] <- up[j] + h
    down[j] <- down[j] - h
    (transform(up) - transform(down)) / (2 * h)
  }))
  matrix(jacobian, length(estimate))
}

.inference_simplex_jacobian <- function(probabilities, reference = c("last", "first")) {
  reference <- match.arg(reference)
  block <- diag(probabilities, nrow = length(probabilities)) - tcrossprod(probabilities)
  if (identical(reference, "first")) block[, -1L, drop = FALSE] else
    block[, seq_len(length(probabilities) - 1L), drop = FALSE]
}

.inference_critical <- function(level, form = c("one_minus", "upper")) {
  form <- match.arg(form)
  switch(form, upper = stats::qnorm((1 + level) / 2),
         one_minus = stats::qnorm(1 - (1 - level) / 2))
}

.latents_memo <- function(store, key, compute, size = 8L) {
  entries <- .latents_cache[[store]] %||% list()
  hit <- Position(\(entry) identical(entry$key, key), entries)
  if (!is.na(hit)) {
    .latents_cache[[store]] <- c(entries[hit], entries[-hit])
    return(entries[[hit]]$value)
  }
  value <- compute()
  .latents_cache[[store]] <- utils::head(c(list(list(key = key, value = value)),
                                           entries), size)
  value
}

.multilpa_observed_hessian <- function(scaled_objective, scaled_gradient,
                                     parameter_scale, step, cache_key = NULL) {
  if (!is.null(cache_key)) {
    return(.latents_memo("observed_information",
                         c(cache_key, list(scale = parameter_scale, step = step)),
                         \() .multilpa_observed_hessian(
                           scaled_objective, scaled_gradient, parameter_scale, step)))
  }
  n_parameters <- length(parameter_scale)
  scaled <- tryCatch(
    stats::optimHess(rep(0, n_parameters), scaled_objective, gr = scaled_gradient,
                     control = list(ndeps = rep(step, n_parameters))),
    error = function(error) {
      stop(sprintf("Observed Hessian failed: %s", conditionMessage(error)))
    })
  natural <- scaled / tcrossprod(parameter_scale)
  eigenvalues <- eigen(natural, symmetric = TRUE, only.values = TRUE)$values
  scaled_eigenvalues <- eigen(scaled, symmetric = TRUE, only.values = TRUE)$values
  condition_ratio <- min(scaled_eigenvalues) / max(scaled_eigenvalues)
  if (any(!is.finite(eigenvalues)) || !is.finite(condition_ratio) ||
      min(scaled_eigenvalues) <= 0 || condition_ratio <= 1e-10) {
    stop(errorCondition(
      "Observed information is not positive definite or is numerically singular; Wald inference is unavailable.",
      class = "latents_singular_information", call = NULL))
  }
  inverse <- tryCatch(solve(scaled), error = function(error) {
    stop(sprintf("Observed information could not be inverted: %s",
                 conditionMessage(error)))
  })
  list(scaled = scaled, natural = natural, condition_ratio = condition_ratio,
       inverse = inverse)
}

.multilpa_opg_inverse <- function(cross) {
  factor <- tryCatch(chol(cross), error = function(error) NULL)
  if (is.null(factor) ||
      min(diag(factor))^2 < 1e-12 * max(diag(factor))^2) {
    stop(errorCondition(paste(
      "The outer product of the group scores is singular; OPG inference is",
      "unavailable. `vcov_type = \"observed\"` uses the curvature instead."),
      class = "latents_singular_information", call = NULL))
  }
  chol2inv(factor)
}

.multilpa_cross_product <- function(scores) {
  stopifnot("`scores` must be a numeric matrix" =
              is.matrix(scores) && is.numeric(scores))
  if (any(!is.finite(scores))) {
    stop(errorCondition("Per-group scores are not finite; robust inference is unavailable.",
                        class = "latents_bad_scores", call = NULL))
  }
  ## A single row cannot support a sandwich: at the estimate the rows sum to
  ## zero, so one row is itself the zero vector up to rounding and the meat is
  ## numerical dust rather than a variance.
  .multilpa_require_clusters(nrow(scores), 1L, "A robust cross-product matrix")
  crossprod(scores)
}

.multilpa_wald_bounds <- function(estimate, standard_error, kind, critical) {
  low <- estimate - critical * standard_error
  high <- estimate + critical * standard_error
  probability <- kind == "probability" & is.finite(standard_error) &
    estimate > 0 & estimate < 1
  if (any(probability)) {
    centre <- stats::qlogis(estimate[probability])
    spread <- critical * standard_error[probability] /
      (estimate[probability] * (1 - estimate[probability]))
    low[probability] <- stats::plogis(centre - spread)
    high[probability] <- stats::plogis(centre + spread)
  }
  positive <- kind == "positive" & is.finite(standard_error) & estimate > 0
  if (any(positive)) {
    spread <- critical * standard_error[positive] / estimate[positive]
    low[positive] <- estimate[positive] * exp(-spread)
    high[positive] <- estimate[positive] * exp(spread)
  }
  list(low = low, high = high)
}

.multilpa_parameter_names <- function(labels) {
  stopifnot(
    "`labels` must carry level, parameter, outcome and term" =
      is.data.frame(labels) &&
      all(c("level", "parameter", "outcome", "term") %in% names(labels))
  )
  stem <- paste(labels$level, labels$parameter, labels$outcome, sep = ".")
  ifelse(is.na(labels$term), stem, paste(stem, labels$term, sep = "."))
}

.multilpa_coefficient_labels <- function(object, scale) {
  .multilpa_tidy_labels(names(.multilpa_coefficients_raw(object, scale)), object)
}

.multilpa_coefficients <- function(object, scale) {
  values <- .multilpa_coefficients_raw(object, scale)
  stats::setNames(unname(values),
                  .multilpa_parameter_names(.multilpa_tidy_labels(names(values), object)))
}

.multilpa_response_coordinates <- function(object, scale) {
  blocks <- object$response_probabilities
  if (is.null(blocks) || length(blocks) == 0L) return(stats::setNames(numeric(0), character(0)))
  prefix <- if (scale == "natural") "response" else "response_logit"
  unlist(lapply(names(blocks), function(indicator) {
    block <- blocks[[indicator]]
    categories <- colnames(block) %||% as.character(seq_len(ncol(block)))
    keep <- if (scale == "natural") seq_len(ncol(block)) else seq_len(ncol(block) - 1L)
    values <- if (scale == "natural") block[, keep, drop = FALSE] else
      log(block[, keep, drop = FALSE]) - log(block[, ncol(block)])
    labels <- as.vector(t(outer(seq_len(nrow(block)), categories[keep],
      function(profile, category) sprintf("%s[%s,%s,%s]", prefix, profile,
                                          indicator, category))))
    stats::setNames(as.vector(t(values)), labels)
  }), use.names = TRUE)
}

.multilpa_response_width <- function(object) {
  blocks <- object$response_probabilities
  if (is.null(blocks) || length(blocks) == 0L) return(0L)
  sum(vapply(blocks, function(block) nrow(block) * (ncol(block) - 1L), numeric(1)))
}

.multilpa_covariance_coordinates <- function(object, scale) {
  stopifnot(inherits(object, "multilpa"), identical(object$covariance_model, "full"),
            scale %in% c("natural", "unconstrained"))
  dimension <- length(.multilpa_continuous_names(object))
  if (dimension == 0L) return(stats::setNames(numeric(0), character(0)))
  shared <- .multilpa_spread_shared(object)
  profiles <- if (shared) 1L else seq_len(object$n_profiles)
  lower <- lower.tri(matrix(0, dimension, dimension), diag = TRUE)
  positions <- which(lower, arr.ind = TRUE)
  unlist(lapply(profiles, function(profile) {
    stopifnot(is.numeric(profile), length(profile) == 1L)
    covariance <- matrix(object$covariances[, , profile], dimension, dimension)
    values <- if (scale == "natural") covariance else t(chol(covariance))
    if (scale == "unconstrained") diag(values) <- log(diag(values))
    prefix <- if (scale == "natural") "covariance" else "cholesky"
    labels <- sprintf("%s[%s,%s,%s]", prefix,
      if (shared) "shared" else profile,
      .multilpa_continuous_names(object)[positions[, 1L]],
      .multilpa_continuous_names(object)[positions[, 2L]])
    if (scale == "unconstrained") {
      labels[positions[, 1L] == positions[, 2L]] <- sub("^cholesky", "log_cholesky",
        labels[positions[, 1L] == positions[, 2L]])
    }
    stats::setNames(values[lower], labels)
  }), use.names = TRUE)
}

.multilpa_coordinate_widths <- function(object, scale) {
  stopifnot("`object` must be a fitted multilpa model" = inherits(object, "multilpa"),
            "`scale` must be natural or unconstrained" =
              length(scale) == 1L && scale %in% c("natural", "unconstrained"))
  n_profiles <- object$n_profiles
  n_types <- object$n_group_classes
  n_continuous <- length(.multilpa_continuous_names(object))
  spread <- if (identical(object$covariance_model, "full")) {
    n_continuous * (n_continuous + 1L) / 2L
  } else n_continuous
  blocks <- object$response_probabilities %||% list()
  spread_width <- if (scale == "unconstrained" && .multilpa_uses_chart(object)) {
    .multilpa_structure_parameters(object$covariance_structure, n_profiles,
                                   n_continuous)
  } else spread * if (.multilpa_spread_shared(object)) 1L else n_profiles
  c(means = n_profiles * n_continuous,
    variances = spread_width,
    response_probabilities = if (scale == "natural") {
      sum(vapply(blocks, length, numeric(1)))
    } else .multilpa_response_width(object),
    extra = .latents_extra_width(object$extra_data, n_profiles),
    profile = n_types * if (scale == "natural") n_profiles else n_profiles - 1L,
    group = if (scale == "natural") n_types else n_types - 1L)
}

.multilpa_free_index <- function(object, scale) {
  widths <- .multilpa_coordinate_widths(object, scale)
  total <- as.integer(sum(widths))
  # A covariance pattern (local dependence) holds the other covariances at
  # zero; their coordinates, in the same lower-triangle order in both scales,
  # are constants of the likelihood like a held block.
  pattern <- object$covariance_pattern
  patterned <- if (is.null(pattern)) integer() else {
    lower <- lower.tri(pattern, diag = TRUE)
    zero <- which(!pattern[lower])
    width <- sum(lower)
    blocks <- widths[["variances"]] %/% width
    as.integer(widths[["means"]] + as.vector(outer(zero, (seq_len(blocks) - 1L) * width, "+")))
  }
  held <- object$fixed %||% character()
  if (length(held) == 0L) return(setdiff(seq_len(total), patterned))
  measurement <- c("means", "variances", "response_probabilities")
  unknown <- setdiff(held, measurement)
  if (length(unknown) > 0L) {
    stop(errorCondition(sprintf(
      "This fit holds %s, which is not a measurement block inference can restore.",
      paste(sprintf("`%s`", unknown), collapse = " or ")),
      class = "latents_bad_fixed", call = NULL))
  }
  offsets <- cumsum(c(0, widths[measurement]))
  frozen <- unlist(lapply(seq_along(measurement), function(position) {
    if (measurement[[position]] %in% held) {
      offsets[[position]] + seq_len(widths[[measurement[[position]]]])
    } else integer(0)
  }), use.names = FALSE)
  setdiff(seq_len(total), c(as.integer(frozen), patterned))
}

.multilpa_response_scores <- function(codes, posteriors, blocks, group_index = NULL) {
  if (is.null(blocks) || length(blocks) == 0L) {
    rows <- if (is.null(group_index)) 1L else max(group_index)
    return(matrix(numeric(0), rows, 0L))
  }
  pieces <- lapply(seq_along(blocks), function(indicator) {
    block <- blocks[[indicator]]
    code <- codes[, indicator]
    observed <- !is.na(code)
    free <- seq_len(ncol(block) - 1L)
    columns <- lapply(seq_len(nrow(block)), function(profile) {
      weight <- posteriors[, profile]
      vapply(free, function(category) {
        indicator_value <- as.numeric(observed & code == category)
        weight * (indicator_value - observed * block[profile, category])
      }, numeric(length(code)))
    })
    do.call(cbind, columns)
  })
  contribution <- do.call(cbind, pieces)
  if (is.null(group_index)) {
    matrix(colSums(contribution), 1L, ncol(contribution))
  } else rowsum(contribution, group_index, reorder = FALSE)
}

.multilpa_full_measurement_score <- function(parameters, expectation, object) {
  stopifnot(is.list(parameters), is.list(expectation), inherits(object, "multilpa"),
            identical(object$covariance_model, "full"))
  dimension <- length(.multilpa_continuous_names(object))
  if (dimension == 0L) return(list(means = numeric(0), covariances = numeric(0)))
  lower <- lower.tri(matrix(0, dimension, dimension), diag = TRUE)
  component_scores <- lapply(seq_len(object$n_profiles), function(profile) {
    stopifnot(is.numeric(profile), length(profile) == 1L)
    covariance <- matrix(parameters$covariances[, , profile], dimension, dimension)
    precision <- chol2inv(chol(covariance))
    moments <- expectation$gaussian_moments[[profile]]
    weights <- expectation$subject_posteriors[, profile]
    residuals <- sweep(moments$expected, 2L, parameters$means[profile, ], "-")
    scatter <- crossprod(residuals, residuals * weights) +
      Reduce(`+`, lapply(moments$adjustments, function(adjustment) {
        stopifnot(is.list(adjustment))
        adjustment$covariance * sum(weights[adjustment$rows])
      }))
    list(means = as.vector(precision %*% colSums(residuals * weights)),
      covariance = 0.5 * (precision %*% scatter %*% precision - sum(weights) * precision))
  })
  profiles <- if (object$variance_model == "equal") 1L else seq_len(object$n_profiles)
  covariance_scores <- lapply(profiles, function(profile) {
    stopifnot(is.numeric(profile), length(profile) == 1L)
    covariance_score <- if (object$variance_model == "equal") {
      Reduce(`+`, lapply(component_scores, `[[`, "covariance"))
    } else component_scores[[profile]]$covariance
    factor <- t(chol(matrix(parameters$covariances[, , profile], dimension, dimension)))
    factor_score <- 2 * covariance_score %*% factor
    diag(factor_score) <- diag(factor_score) * diag(factor)
    factor_score[lower]
  })
  list(means = unlist(lapply(component_scores, `[[`, "means"), use.names = FALSE),
       covariances = unlist(covariance_scores, use.names = FALSE))
}

.multilpa_response_bound <- function(object) {
  blocks <- object$response_probabilities %||% list()
  floor <- .multilpa_probability_floor(object)
  pieces <- lapply(names(blocks), function(indicator) {
    block <- blocks[[indicator]]
    categories <- colnames(block)
    at <- block <= floor
    held <- at | at[, ncol(block)]
    spell <- function(positions, kind) {
      sprintf("measurement.%s.profile_%d.%s:%s", kind, positions[, 1L],
              indicator, categories[positions[, 2L]])
    }
    list(natural = spell(which(held, arr.ind = TRUE), "response"),
         unconstrained = spell(which(held[, -ncol(block), drop = FALSE],
                                     arr.ind = TRUE), "response_logit"))
  })
  list(natural = unlist(lapply(pieces, `[[`, "natural")) %||% character(),
       unconstrained = unlist(lapply(pieces, `[[`, "unconstrained")) %||% character())
}

.multilpa_probability_floor <- function(object) {
  max((object$min_probability %||% 1e-10) * (1 + 1e-7), 1e-6)
}

coef.multilpa <- function(object, scale = c("natural", "unconstrained"), ...) {
  stopifnot(inherits(object, "multilpa"))
  .multilpa_coefficients(object, match.arg(scale))
}

vcov.multilpa <- function(object, data = NULL, scale = c("natural", "unconstrained"), ...) {
  stopifnot(inherits(object, "multilpa"))
  scale <- match.arg(scale)
  # `data` is no longer required: a fit carries the columns it was built from,
  # and `parameter_inference()` falls back to them.
  information <- parameter_inference(object, data, ...)
  if (scale == "natural") return(attr(information, "covariance"))
  covariance <- attr(information, "covariance_unconstrained")
  # The bootstrap refits each resample in its own coordinates and reads the
  # natural parameters only, so it has no estimation-scale covariance. Saying
  # so is the answer; a NULL would flow silently into the caller's next step.
  if (is.null(covariance)) {
    stop(errorCondition(paste(
      "The bootstrap has no covariance on the estimation scale: it reads the",
      "natural parameters of each refit. Use `scale = \"natural\"`, or the",
      "Wald path (`method = \"wald\"`) for the estimation scale."),
      class = "latents_unsupported_inference", call = NULL))
  }
  covariance
}

confint.multilpa <- function(object, parm, level = 0.95, data = NULL, ...) {
  stopifnot(inherits(object, "multilpa"), is.numeric(level), length(level) == 1L,
            is.finite(level), level > 0, level < 1)
  estimates <- coef.multilpa(object)
  ## One call, not one through `vcov()`: the bootstrap interval is the
  ## percentile interval this table already carries, and reaching it through
  ## the covariance would rebuild it as `estimate +/- z * se`, a different
  ## interval from the one `parameter_inference()` reports for the same fit.
  information <- parameter_inference(object, data = data, level = level, ...)
  covariance <- attr(information, "covariance")
  ## A held measurement coefficient is reported by coef() -- it is part of the
  ## model -- but it was not estimated here and has no interval. The default is
  ## therefore what the covariance actually covers.
  estimated <- rownames(covariance)
  if (missing(parm)) parm <- estimated
  if (is.numeric(parm)) {
    if (anyNA(parm) || any(!is.finite(parm)) || any(parm != floor(parm)) ||
        any(parm < 1) || any(parm > length(estimates))) {
      stop(errorCondition("Invalid coefficient indices in parm.",
                          class = "latents_bad_argument", call = NULL))
    }
    parm <- names(estimates)[parm]
  }
  if (!is.character(parm) || anyNA(parm) || !all(parm %in% names(estimates))) {
    stop(errorCondition("parm must identify existing coefficient names or indices.",
                        class = "latents_bad_argument", call = NULL))
  }
  held <- setdiff(parm, estimated)
  if (length(held) > 0L) {
    stop(errorCondition(sprintf(
      "%s %s held fixed by this fit, so %s carr%s no confidence interval.",
      paste(sprintf("`%s`", held), collapse = ", "),
      if (length(held) == 1L) "was" else "were",
      if (length(held) == 1L) "it" else "they",
      if (length(held) == 1L) "ies" else "y"),
      class = "latents_held_parameter", call = NULL))
  }
  # The intervals parameter_inference() reports, whichever path made them:
  # percentile for the bootstrap, and for Wald ones formed where the parameter
  # is unbounded, so the two verbs can never disagree.
  intervals <- cbind(information$conf_low, information$conf_high)
  rownames(intervals) <- rownames(covariance)
  intervals <- intervals[parm, , drop = FALSE]
  colnames(intervals) <- paste0(format(100 * c((1 - level) / 2, (1 + level) / 2), trim = TRUE), "%")
  intervals
}

.multilpa_check_regularity <- function(object, vcov_type, boundary = "error") {
  n_groups <- sum(.multilpa_inference_groups(object, observed_only = TRUE))
  if (vcov_type %in% c("robust", "opg") && n_groups <= object$n_parameters) {
    stop(errorCondition(sprintf(
      "Robust and OPG inference need more groups than parameters; this fit has %d groups and %d parameters.",
      n_groups, object$n_parameters),
      class = "latents_too_few_groups", call = NULL))
  }
  if (!isTRUE(object$converged)) {
    stop(errorCondition("Inference requires a converged fit.",
                        class = "latents_no_converge", call = NULL))
  }
  ## A bound-active value that this fit held fixed is a constant of the
  ## conditional likelihood, not an estimate sitting on its boundary, so it does
  ## not disqualify the parameters that were actually estimated.
  held <- object$fixed %||% character()
  if (isTRUE(object$boundary) && !("variances" %in% held)) {
    stop(errorCondition("Wald inference is unavailable for a bound-active fit.",
                        class = "latents_boundary_fit", call = NULL))
  }
  ## `boundary = "fix"` asks for the bound-active response probabilities to be
  ## held at their bound and the rest estimated conditionally on them.
  response <- if ("response_probabilities" %in% held ||
                  identical(boundary, "fix")) NULL else
    unlist(object$response_probabilities, use.names = FALSE)
  if (length(response) > 0L &&
      any(response <= .multilpa_probability_floor(object))) {
    stop(errorCondition(
      paste("Wald inference is unavailable for bound-active categorical response",
            "probabilities. `boundary = \"fix\"` holds them at their bound and",
            "reports the other parameters conditionally on them."),
      class = "latents_boundary_fit", call = NULL))
  }
  if (length(object$count_means) > 0L && any(object$count_means <= 1e-8)) {
    stop(errorCondition(
      "Wald inference is unavailable when a count mean is estimated at zero.",
      class = "latents_boundary_fit", call = NULL))
  }
  if (length(object$count_dispersion) > 0L &&
      any(object$count_dispersion <= .latents_min_dispersion * (1 + 1e-6))) {
    stop(errorCondition(paste(
      "A negative-binomial dispersion is at its floor (the Poisson limit), where",
      "Wald inference does not apply; refit with `count_model = \"poisson\"`."),
      class = "latents_boundary_fit", call = NULL))
  }
  if (any(object$profile_probabilities <= 0) || any(object$group_probabilities <= 0)) {
    stop(errorCondition(
      "Wald inference requires strictly positive mixing probabilities.",
      class = "latents_boundary_fit", call = NULL))
  }
  invisible(NULL)
}

.multilpa_number_single_level <- function(object, data) {
  if (isTRUE(object$single_level) && !object$id %in% names(data) &&
      nrow(data) == object$n_observations) {
    data[[object$id]] <- object$group_values[seq_len(nrow(data))]
  }
  data
}

.multilpa_inference_matrix <- function(object, data) {
  data <- .multilpa_number_single_level(object, data)
  if (nrow(data) != object$n_observations ||
      !all(c(object$vars, object$id) %in% names(data)) ||
      anyDuplicated(names(data)) ||
      !all(vapply(data[, .multilpa_continuous_names(object), drop = FALSE],
                  is.numeric, logical(1)))) {
    stop(errorCondition(
      "data must contain the original numeric indicators and group column.",
      class = "latents_bad_inference_data", call = NULL))
  }
  group_index <- match(data[[object$id]], object$group_values)
  if (!identical(group_index, object$group_index)) {
    stop(errorCondition(
      "data must retain the original group identifiers and row order.",
      class = "latents_bad_inference_data", call = NULL))
  }
  ## Only the Gaussian indicators form the numeric matrix; the categorical ones
  ## are re-encoded from `data` rather than taken from the fit, so that supplying
  ## the wrong categorical columns is caught rather than silently accepted.
  continuous <- .multilpa_continuous_names(object)
  ## as.matrix() of a zero-column frame is logical, and the expectation demands
  ## a numeric matrix, so an all-categorical fit needs the mode forced.
  x <- if (length(continuous) == 0L) matrix(numeric(0), nrow(data), 0L) else
    .multilpa_center_like(object, as.matrix(data[, continuous, drop = FALSE]))
  if (any(is.infinite(x)) || any(is.nan(x)) ||
      (anyNA(x) && !identical(object$missing, "fiml"))) {
    stop(errorCondition(
      "data contain unsupported missing or non-finite indicators.",
      class = "latents_bad_inference_data", call = NULL))
  }
  if (!is.null(object$indicator_data) && ncol(x) > 0L &&
      !isTRUE(all.equal(x, object$indicator_data, tolerance = 1e-12))) {
    stop(errorCondition(
      "data must reproduce the original indicator data, including row order and names.",
      class = "latents_bad_inference_data", call = NULL))
  }
  codes <- NULL
  if (length(object$categorical %||% character()) > 0L) {
    encoded <- .multilpa_encode_categorical(data[, object$categorical, drop = FALSE])
    codes <- encoded$codes
    if (!identical(unname(codes), unname(object$categorical_data)) ||
        !identical(encoded$levels, object$categorical_levels)) {
      stop(errorCondition(
        "data must reproduce the original categorical indicators, including their categories and row order.",
        class = "latents_bad_inference_data", call = NULL))
    }
  }
  if (!is.null(object$extra_data)) {
    extra <- .latents_prepare_extra(data, object$ordinal, object$count,
                                    object$missing %||% "error")
    # A carrier can hold direct effects alone, with no indicator to compare.
    if (length(c(object$ordinal, object$count)) > 0L &&
        (!identical(unname(extra$ordinal), unname(object$extra_data$ordinal)) ||
           !identical(extra$ordinal_levels, object$extra_data$ordinal_levels) ||
           !identical(unname(extra$count), unname(object$extra_data$count)))) {
      stop(errorCondition(
        "data must reproduce the original ordinal and count indicators.",
        class = "latents_bad_inference_data", call = NULL))
    }
    direct <- object$extra_data$direct
    if (!is.null(direct) && !identical(
      unname(.latents_direct_like(direct, data)$covariates), unname(direct$covariates))) {
      stop(errorCondition(
        "data must reproduce the original direct-effect covariates and row order.",
        class = "latents_bad_inference_data", call = NULL))
    }
  }
  centers <- if (ncol(x) > 0L) colMeans(x, na.rm = TRUE) else numeric(0)
  list(x = if (ncol(x) > 0L) sweep(x, 2L, centers, "-") else x,
       centers = centers, codes = codes)
}

.multilpa_validate_bootstrap_data <- function(object, data) {
  stopifnot(inherits(object, "multilpa"), is.data.frame(data))
  data <- .multilpa_number_single_level(object, data)
  prepared <- .multilpa_inference_matrix(object, data)
  .multilpa_check_alignment(object, data)
  if (!is.null(object$weights)) {
    supplied_weights <- tryCatch(
      .latents_sampling_weights(data, object$weights, object$group_index,
                               object$n_groups),
      error = function(condition) {
        stop(errorCondition(paste("data must reproduce the fitted sampling weights:",
                                  conditionMessage(condition)),
                            class = "latents_bad_inference_data", call = NULL))
      })
    if (!isTRUE(all.equal(unname(supplied_weights),
                          unname(object$sampling_weights), tolerance = 1e-12))) {
      stop(errorCondition("data must reproduce the fitted sampling weights.",
                          class = "latents_bad_inference_data", call = NULL))
    }
  }
  parameters <- .multilpa_decode(.multilpa_coefficients(object, "unconstrained"),
                                 object)
  if (length(prepared$centers)) {
    parameters$means <- sweep(parameters$means, 2L, prepared$centers, "-")
  }
  likelihood <- .multilpa_expectation(
    prepared$x, object$group_index, parameters, prepared$codes,
    unname(object$sampling_weights), object$extra_data)$log_likelihood
  if (!is.finite(likelihood) ||
      abs(likelihood - object$log_likelihood) >
        1e-8 * (1 + abs(object$log_likelihood))) {
    stop(errorCondition("data must reproduce the fitted log likelihood.",
                        class = "latents_bad_inference_data", call = NULL))
  }
  data
}

.latents_vuong_parts <- function(fit) {
  inference <- parameter_inference(fit, vcov_type = "robust")
  scores <- attr(inference, "group_scores_conditioned") %||%
    attr(inference, "group_scores")
  information <- attr(inference, "hessian_conditioned") %||%
    attr(inference, "hessian")
  if (is.null(scores) || is.null(information)) {
    stop(errorCondition(paste(
      "The Vuong-Lo-Mendell-Rubin test is unavailable for this model:",
      "parameter_inference() does not provide per-unit scores and observed information."),
      class = "latents_invalid_lmr", call = NULL))
  }
  list(scores = scores, information = information,
       log_likelihood = fit$log_likelihood, n_parameters = fit$n_parameters,
       n_units = sum(.multilpa_inference_groups(fit)))
}

.latents_imhof_upper <- function(q, lambda) {
  stopifnot(is.numeric(q), length(q) == 1L, is.finite(q),
            is.numeric(lambda), all(is.finite(lambda)))
  lambda <- lambda[lambda != 0]
  if (length(lambda) == 0L) return(as.numeric(q < 0))
  if (q < 0) return(1 - .latents_imhof_upper(-q, -lambda))
  if (q == 0 && all(lambda > 0)) return(1)
  if (all(lambda < 0)) return(0)
  # P(sum lambda_j X_j > q) = P(sum (lambda_j / c) X_j > q / c): the integral
  # is taken on weights of unit size, so its breakpoints and tolerances do
  # not depend on the weights' units (weights of size 1e-6 failed to
  # integrate before).
  size <- max(abs(lambda))
  lambda <- lambda / size
  q <- q / size
  integrand <- function(u) {
    theta <- 0.5 * vapply(u, function(value) sum(atan(lambda * value)), numeric(1)) -
      0.5 * q * u
    log_rho <- vapply(u, function(value) {
      # log(1 + exp(2 z)) without squaring huge integration coordinates or
      # multiplying many small factors; both overflow at extreme weight ratios.
      logs <- log(abs(lambda)) + log(value)
      sum(0.5 * pmax(logs, 0) + 0.25 * log1p(exp(-2 * abs(logs))))
    }, numeric(1))
    ifelse(u == 0, 0.5 * (sum(lambda) - q),
           sin(theta) * exp(-log(u) - log_rho))
  }
  inaccurate <- function(reason) {
    stop(errorCondition(sprintf(paste(
      "The tail probability of the weighted chi-square distribution %s",
      "(statistic %g, %d weights); the p-value cannot be reported."),
      reason, q, length(lambda)), class = "latents_inaccurate_probability", call = NULL))
  }
  segment <- function(lower, upper) {
    tryCatch(stats::integrate(integrand, lower, upper, rel.tol = 1e-11,
                              abs.tol = 1e-14, subdivisions = 2000L)$value,
             error = function(condition) {
               inaccurate(sprintf("could not be integrated over [%g, %g]: %s", lower,
                                  upper, conditionMessage(condition)))
             })
  }
  clamp <- function(integral) min(1, max(0, 0.5 + integral / pi))
  if (any(lambda == 0)) inaccurate("has weights beyond representable relative precision")
  scales <- 1 / abs(lambda)
  # With q = 0 the lead is the whole integral. Past u its integrand is at
  # most u^(-1 - n/2) / prod |lambda_j|^(1/2), so the rest is at most
  # (2 / n) u^(-n/2) / prod |lambda_j|^(1/2) (Imhof 1961); the lead ends
  # where that bound is 1e-12, and nothing is left to an infinite range.
  n_weights <- length(lambda)
  truncation <- exp(2 / n_weights *
    (log(2 / n_weights) - log(1e-12) - 0.5 * sum(log(abs(lambda)))))
  lead_end <- if (q > 0) 2 * pi / q else max(truncation, 1e3 * max(scales))
  if (!is.finite(lead_end) || any(!is.finite(scales))) {
    inaccurate("has weights or a statistic beyond the integration range")
  }
  top <- lead_end
  decades <- 10^seq(floor(log10(min(scales))), ceiling(log10(top)))
  breaks <- sort(unique(c(0, scales, decades)))
  breaks <- c(breaks[breaks < lead_end], lead_end)
  lead <- sum(vapply(seq_len(length(breaks) - 1L), function(index) {
    segment(breaks[index], breaks[index + 1L])
  }, numeric(1)))
  if (q <= 0) return(clamp(lead))
  half_period <- 2 * pi / q
  piece <- function(k) segment(lead_end + k * half_period, lead_end + (k + 1) * half_period)
  pieces <- vapply(seq_len(20L) - 1L, piece, numeric(1))
  previous <- .latents_wynn(lead + cumsum(pieces))
  # Each round adds 20 half-periods until two successive estimates agree;
  # the number of rounds is bounded, and reaching the bound is reported.
  round <- 0L
  while (round < 25L) {
    round <- round + 1L
    pieces <- c(pieces, vapply(length(pieces) + seq_len(20L) - 1L, piece, numeric(1)))
    current <- .latents_wynn(lead + cumsum(pieces))
    if (abs(current - previous) < 1e-10) return(clamp(current))
    previous <- current
  }
  inaccurate("did not settle")
}

.latents_lmr_table <- function(x) {
  table <- .latents_named_table(x)
  structures <- ifelse(is.na(table$model), "", table$model)
  usable <- table$converged %in% TRUE
  find <- function(n_profiles, n_group_classes, model) {
    which(usable & table$n_profiles == n_profiles &
            table$n_group_classes == n_group_classes & structures == model)
  }
  pairs <- do.call(rbind, lapply(which(usable), function(at) {
    profile_step <- find(table$n_profiles[at] + 1L, table$n_group_classes[at], structures[at])
    group_step <- find(table$n_profiles[at], table$n_group_classes[at] + 1L, structures[at])
    rbind(if (length(profile_step) == 1L) {
      data.frame(direction = "profiles", null = at, alternative = profile_step)
    }, if (length(group_step) == 1L) {
      data.frame(direction = "group_classes", null = at, alternative = group_step)
    })
  }))
  if (is.null(pairs) || nrow(pairs) == 0L) {
    stop(errorCondition(paste(
      "No two converged candidates of this grid differ by one profile or one",
      "group class, so there is no Lo-Mendell-Rubin test to compute."),
      class = c("latents_no_lmr", "latents_nothing_to_plot"), call = NULL))
  }
  # Each candidate is scored once, whatever the number of comparisons it is in.
  involved <- sort(unique(c(pairs$null, pairs$alternative)))
  scored <- lapply(stats::setNames(involved, involved), function(at) {
    notes <- character()
    parts <- tryCatch(
      withCallingHandlers(.latents_vuong_parts(get_candidate(x, table$candidate[at])),
        warning = function(condition) {
          notes <<- c(notes, conditionMessage(condition))
          invokeRestart("muffleWarning")
        }),
      latents_boundary_fit = function(condition) condition,
      latents_invalid_lmr = function(condition) condition,
      latents_singular_information = function(condition) condition,
      latents_unsupported_inference = function(condition) condition,
      latents_no_converge = function(condition) condition,
      latents_too_few_groups = function(condition) condition)
    list(parts = parts, notes = notes)
  })
  rows <- lapply(seq_len(nrow(pairs)), function(index) {
    null <- scored[[as.character(pairs$null[index])]]
    alternative <- scored[[as.character(pairs$alternative[index])]]
    failed <- Filter(function(entry) inherits(entry$parts, "condition"),
                     list(null = null, alternative = alternative))
    statistics <- if (length(failed) > 0L) {
      data.frame(n_units = NA_integer_, parameters_added = NA_integer_, lr = NA_real_,
                 vlmr_p = NA_real_, adjusted_lr = NA_real_, almr_p = NA_real_,
                 reference_mean = NA_real_, reference_sd = NA_real_)
    } else tryCatch(.latents_vuong_row(alternative$parts, null$parts),
      latents_invalid_lmr = identity,
      latents_singular_information = identity,
      latents_inaccurate_probability = identity)
    comparison_reason <- character()
    if (inherits(statistics, "condition")) {
      comparison_reason <- conditionMessage(statistics)
      statistics <- data.frame(n_units = NA_integer_, parameters_added = NA_integer_,
                               lr = NA_real_, vlmr_p = NA_real_, adjusted_lr = NA_real_,
                               almr_p = NA_real_, reference_mean = NA_real_,
                               reference_sd = NA_real_)
    }
    reasons <- c(vapply(names(failed), function(role) {
      sprintf("%s model: %s", role, conditionMessage(failed[[role]]$parts))
    }, character(1)), comparison_reason, unique(c(null$notes, alternative$notes)))
    alternative_at <- pairs$alternative[index]
    data.frame(direction = pairs$direction[index],
               null_candidate = table$candidate[pairs$null[index]],
               alternative_candidate = table$candidate[alternative_at],
               n_profiles = table$n_profiles[alternative_at],
               n_group_classes = table$n_group_classes[alternative_at],
               model = table$model[alternative_at], statistics,
               note = if (length(reasons) == 0L) NA_character_ else
                 paste(reasons, collapse = " | "),
               stringsAsFactors = FALSE)
  })
  result <- do.call(rbind, rows)
  rownames(result) <- NULL
  result
}

.multilpa_completed_data <- function(imputed) {
  bad <- function(message) {
    stop(errorCondition(message, class = "latents_bad_data", call = NULL))
  }
  if (inherits(imputed, "mids")) {
    if (!requireNamespace("mice", quietly = TRUE)) {
      stop(errorCondition(paste(
        "A `mids` object needs the mice package to be completed.",
        "Install it with install.packages(\"mice\")."),
        class = "latents_missing_package", call = NULL))
    }
    imputed <- mice::complete(imputed, action = "all")
  }
  if (!is.list(imputed) || is.data.frame(imputed) ||
      !all(vapply(imputed, is.data.frame, logical(1)))) {
    bad("`imputed` must be a list of completed data frames, or a `mids` object.")
  }
  if (length(imputed) < 2L) {
    bad("`imputed` must hold at least two completed data sets; one is not pooling.")
  }
  first <- imputed[[1L]]
  same_shape <- vapply(imputed, function(frame) {
    identical(names(frame), names(first)) && nrow(frame) == nrow(first)
  }, logical(1))
  if (!all(same_shape)) {
    bad(sprintf(paste(
      "Every completed data set must have the same columns and rows; set%s %s",
      "differ%s from the first."),
      if (sum(!same_shape) > 1L) "s" else "",
      paste(which(!same_shape), collapse = ", "),
      if (sum(!same_shape) > 1L) "" else "s"))
  }
  unname(imputed)
}

.multilpa_pool_step <- function(index, stage, expr) {
  tryCatch(expr, error = function(error) {
    stop(errorCondition(sprintf(
      "Imputation %d failed at %s (%s): %s", index, stage,
      class(error)[1L], conditionMessage(error)),
      class = "latents_pooling_failed", call = NULL))
  })
}

.multilpa_pool_keys <- function(table) {
  paste(table$level, table$outcome, table$term, table$parameter, sep = "\r")
}

.multilpa_rubin_covariance <- function(tables, fits, vcov_type) {
  m <- length(tables)
  covariances <- lapply(seq_len(m), function(index) {
    attr(tables[[index]], "covariance") %||%
      vcov(fits[[index]], vcov_type = vcov_type)
  })
  invisible(lapply(seq_len(m), function(index) {
    stopifnot("each covariance must match its inference table row for row" =
                isTRUE(all.equal(sqrt(diag(covariances[[index]])),
                                 tables[[index]]$standard_error,
                                 check.attributes = FALSE, tolerance = 1e-8)))
  }))
  within <- Reduce(`+`, covariances) / m
  estimates <- do.call(rbind, lapply(tables, `[[`, "estimate"))
  total <- within + (1 + 1 / m) * stats::cov(estimates)
  dimnames(total) <- dimnames(covariances[[1L]])
  total
}

.multilpa_pool_long <- function(tables) {
  do.call(rbind, lapply(seq_along(tables), function(index) {
    data.frame(imputation = index,
               tables[[index]][c("level", "outcome", "term", "parameter",
                                 "estimate", "standard_error")],
               row.names = NULL, stringsAsFactors = FALSE)
  }))
}

.multilpa_pool_fit_frame <- function(fits, alignments) {
