    n_parameters = vapply(fits, function(fit) as.numeric(fit$n_parameters),
                          numeric(1)),
    converged = vapply(fits, function(fit) isTRUE(fit$converged), logical(1)),
    profile_order = vapply(alignments, function(alignment) {
