.multilpa_spread_shared <- function(object) {
  if (.multilpa_uses_chart(object)) {
    return(identical(object$covariance_structure, "EII"))
  }
  identical(object$variance_model, "equal")
}

.multilpa_chart_cholesky_positions <- function(d) {
  positions <- which(lower.tri(matrix(0, d, d), diag = TRUE), arr.ind = TRUE)
  positions[!(positions[, 1L] == d & positions[, 2L] == d), , drop = FALSE]
}

.multilpa_chart_rotation_pairs <- function(d) {
  which(upper.tri(matrix(0, d, d)), arr.ind = TRUE)
}

.multilpa_fitted_blocks <- function(object) {
  d <- length(.multilpa_continuous_names(object))
  lapply(seq_len(object$n_profiles), function(profile) {
    if (is.null(object$covariances)) {
      diag(unname(object$variances[profile, ]), d)
    } else {
      block <- unname(matrix(object$covariances[, , profile], d, d))
      (block + t(block)) / 2
    }
  })
}

.multilpa_chart_anchor <- function(blocks, chart) {
  if (!identical(chart$form, "rotation")) return(NULL)
  if (chart$rotation_shared) {
    combination <- Reduce(`+`, lapply(seq_along(blocks), function(profile) {
      sqrt(profile + 1) * blocks[[profile]]
    }))
    return(list(eigen(combination, symmetric = TRUE)$vectors))
  }
  lapply(blocks, function(block) eigen(block, symmetric = TRUE)$vectors)
}

.multilpa_chart_encode <- function(object) {
  continuous <- .multilpa_continuous_names(object)
  k <- object$n_profiles
  d <- length(continuous)
  chart <- .multilpa_chart(object$covariance_structure, k, d)
  blocks <- .multilpa_fitted_blocks(object)
  anchor <- .multilpa_chart_anchor(blocks, chart)
  log_volumes <- vapply(blocks, function(block) {
    as.numeric(determinant(block, logarithm = TRUE)$modulus) / d
  }, numeric(1))
  label <- function(shared, row) if (shared) "shared" else as.character(row)
  volume_values <- if (chart$volume_shared) mean(log_volumes) else log_volumes
  volume_names <- sprintf("log_volume[%s]", vapply(seq_len(chart$widths[["volume"]]),
    function(row) label(chart$volume_shared, row), character(1)))
  # The per-profile log shapes, before any sharing: log eigenvalues along the
  # anchor minus the log volume.
  profile_log_shapes <- function() {
    lapply(seq_len(k), function(profile) {
      block <- blocks[[profile]]
      values <- switch(chart$form,
        diagonal = diag(block),
        rotation = diag(crossprod(anchor[[chart$rotation_of[profile]]],
                                  block %*% anchor[[chart$rotation_of[profile]]])))
      log(values) - log_volumes[profile]
    })
  }
  shape <- if (identical(chart$form, "spherical")) {
    list(values = numeric(0), names = character(0), scale = numeric(0))
  } else if (chart$form %in% c("diagonal", "rotation")) {
    shapes <- profile_log_shapes()
    rows <- if (chart$shape_shared) list(Reduce(`+`, shapes) / k) else shapes
    free <- seq_len(d - 1L)
    list(values = unlist(lapply(rows, function(row) row[free]), use.names = FALSE),
         names = unlist(lapply(seq_along(rows), function(row) {
           sprintf("log_shape[%s,%s]", label(chart$shape_shared, row), continuous[free])
         }), use.names = FALSE),
         scale = rep(1, length(rows) * length(free)))
  } else {
    positions <- .multilpa_chart_cholesky_positions(d)
    matrices <- if (chart$shape_shared) {
      list(Reduce(`+`, lapply(seq_len(k), function(profile) {
        blocks[[profile]] / exp(log_volumes[profile])
      })) / k)
    } else {
      lapply(seq_len(k), function(profile) {
        blocks[[profile]] / exp(volume_values[chart$volume_of[profile]])
      })
    }
    pieces <- lapply(seq_along(matrices), function(row) {
      factor <- t(chol(matrices[[row]]))
      on_diagonal <- positions[, 1L] == positions[, 2L]
      values <- factor[positions]
      values[on_diagonal] <- log(values[on_diagonal])
      kind <- ifelse(on_diagonal, "log_shape_cholesky", "shape_cholesky")
      list(values = values,
           names = sprintf("%s[%s,%s,%s]", kind, label(chart$shape_shared, row),
                           continuous[positions[, 1L]], continuous[positions[, 2L]]),
           scale = ifelse(on_diagonal, 1, sqrt(diag(matrices[[row]]))[positions[, 1L]]))
    })
    list(values = unlist(lapply(pieces, `[[`, "values"), use.names = FALSE),
         names = unlist(lapply(pieces, `[[`, "names"), use.names = FALSE),
         scale = unlist(lapply(pieces, `[[`, "scale"), use.names = FALSE))
  }
  pairs <- .multilpa_chart_rotation_pairs(d)
  rotation_names <- if (chart$rotation_rows == 0L) character(0) else {
    unlist(lapply(seq_len(chart$rotation_rows), function(row) {
      sprintf("rotation[%s,%s,%s]", label(chart$rotation_shared, row),
              continuous[pairs[, 1L]], continuous[pairs[, 2L]])
    }), use.names = FALSE)
  }
  values <- c(volume_values, shape$values, rep(0, length(rotation_names)))
  names(values) <- c(volume_names, shape$names, rotation_names)
  stopifnot("the chart must have one coordinate per structure parameter" =
              length(values) == chart$width &&
              chart$width == .multilpa_structure_parameters(chart$structure, k, d))
  list(values = values,
       scale = c(rep(1, length(volume_values)), shape$scale,
                 rep(1, length(rotation_names))),
       chart = chart, anchor = anchor)
}

.multilpa_chart_map <- function(phi, chart, anchor, derivatives = FALSE) {
  stopifnot("`phi` must carry one value per chart coordinate" =
              is.numeric(phi) && length(phi) == chart$width)
  phi <- unname(phi)
  d <- chart$d
  k <- chart$k
  identity <- diag(d)
  volume_block <- phi[chart$offsets[["volume"]] + seq_len(chart$widths[["volume"]])]
  shape_index <- function(row) {
    chart$offsets[["shape"]] + (row - 1L) * chart$per_shape + seq_len(chart$per_shape)
  }
  rotation_index <- function(row) {
    chart$offsets[["rotation"]] + (row - 1L) * chart$per_rotation +
      seq_len(chart$per_rotation)
  }
  # Full log shape vectors (diagonal and rotation forms) or Cholesky factors.
  log_shape <- function(row) {
    if (identical(chart$form, "spherical") || d == 1L) return(numeric(d))
    free <- phi[shape_index(row)]
    c(free, -sum(free))
  }
  positions <- .multilpa_chart_cholesky_positions(d)
  cholesky_factor <- function(row) {
    factor <- matrix(0, d, d)
    factor[positions] <- phi[shape_index(row)]
    on_diagonal <- positions[positions[, 1L] == positions[, 2L], , drop = FALSE]
    logs <- phi[shape_index(row)][positions[, 1L] == positions[, 2L]]
    factor[on_diagonal] <- exp(logs)
    factor[d, d] <- exp(-sum(logs))
    factor
  }
  pairs <- .multilpa_chart_rotation_pairs(d)
  rotation <- function(row) {
    skew <- matrix(0, d, d)
    skew[pairs] <- phi[rotation_index(row)]
    skew[pairs[, c(2L, 1L), drop = FALSE]] <- -phi[rotation_index(row)]
    inverse <- solve(identity - skew)
    cayley <- inverse %*% (identity + skew)
    list(matrix = anchor[[row]] %*% cayley, inverse = inverse, cayley = cayley)
  }
  shapes <- if (chart$form == "cholesky") {
    lapply(seq_len(chart$shape_rows), cholesky_factor)
  } else lapply(seq_len(max(chart$shape_rows, 1L)), log_shape)
  rotations <- if (chart$rotation_rows > 0L) lapply(seq_len(chart$rotation_rows), rotation)
  profile_parts <- lapply(seq_len(k), function(profile) {
    lambda <- exp(volume_block[chart$volume_of[profile]])
    shape_row <- if (chart$shape_rows == 0L) 1L else chart$shape_of[profile]
    orientation <- if (chart$rotation_rows > 0L) {
      rotations[[chart$rotation_of[profile]]]$matrix
    } else identity
    unit_sigma <- if (chart$form == "cholesky") {
      tcrossprod(shapes[[shape_row]])
    } else {
      orientation %*% (exp(shapes[[shape_row]]) * t(orientation))
    }
    list(lambda = lambda, shape_row = shape_row, orientation = orientation,
         sigma = lambda * unit_sigma)
  })
  sigma <- lapply(profile_parts, `[[`, "sigma")
  if (!derivatives) return(list(sigma = sigma))
  width <- chart$width
  jacobian <- lapply(seq_len(k), function(profile) {
    part <- profile_parts[[profile]]
    columns <- matrix(0, d * d, width)
    columns[, chart$offsets[["volume"]] + chart$volume_of[profile]] <- as.vector(part$sigma)
    if (chart$shape_rows > 0L && chart$per_shape > 0L) {
      index <- shape_index(part$shape_row)
      if (chart$form == "cholesky") {
        factor <- shapes[[part$shape_row]]
        columns[, index] <- vapply(seq_len(nrow(positions)), function(position) {
          row <- positions[position, 1L]
          column <- positions[position, 2L]
          change <- matrix(0, d, d)
          if (row == column) {
            change[row, row] <- factor[row, row]
            change[d, d] <- -factor[d, d]
          } else change[row, column] <- 1
          as.vector(part$lambda * (change %*% t(factor) + factor %*% t(change)))
        }, numeric(d * d))
      } else {
        values <- exp(shapes[[part$shape_row]])
        columns[, index] <- vapply(seq_len(d - 1L), function(free) {
          direction <- numeric(d)
          direction[free] <- 1
          direction[d] <- -1
          as.vector(part$lambda * part$orientation %*%
                      ((values * direction) * t(part$orientation)))
        }, numeric(d * d))
      }
    }
    if (chart$rotation_rows > 0L && chart$per_rotation > 0L) {
      row <- chart$rotation_of[profile]
      piece <- rotations[[row]]
      scaled <- exp(shapes[[part$shape_row]])
      columns[, rotation_index(row)] <- vapply(seq_len(nrow(pairs)), function(pair) {
        skew <- matrix(0, d, d)
        skew[pairs[pair, 1L], pairs[pair, 2L]] <- 1
        skew[pairs[pair, 2L], pairs[pair, 1L]] <- -1
        change <- anchor[[row]] %*% piece$inverse %*% skew %*% (identity + piece$cayley)
        half <- change %*% (scaled * t(part$orientation))
        as.vector(part$lambda * (half + t(half)))
      }, numeric(d * d))
    }
    columns
  })
  list(sigma = sigma, jacobian = jacobian)
}

.multilpa_chart_decode <- function(phi, object) {
  d <- length(.multilpa_continuous_names(object))
  chart <- .multilpa_chart(object$covariance_structure, object$n_profiles, d)
  anchor <- .multilpa_chart_anchor(.multilpa_fitted_blocks(object), chart)
  sigma <- .multilpa_chart_map(phi, chart, anchor)$sigma
  variances <- matrix(vapply(sigma, diag, numeric(d)), object$n_profiles, d,
                      byrow = TRUE)
  if (!.multilpa_is_ellipsoidal(object$covariance_structure)) {
    return(list(variances = variances))
  }
  list(variances = variances,
       covariances = array(unlist(sigma, use.names = FALSE),
                           c(d, d, object$n_profiles)))
}

.multilpa_chart_scores <- function(parameters, expectation, x, object, phi,
                                   group_index = NULL) {
  d <- ncol(x)
  chart <- .multilpa_chart(object$covariance_structure, object$n_profiles, d)
  anchor <- .multilpa_chart_anchor(.multilpa_fitted_blocks(object), chart)
  jacobian <- .multilpa_chart_map(phi, chart, anchor, derivatives = TRUE)$jacobian
  gradients <- .multilpa_profile_gradients(parameters, expectation, x, group_index)
  list(means = gradients$means,
       covariances = Reduce(`+`, lapply(seq_len(object$n_profiles), function(profile) {
         gradients$covariance[[profile]] %*% jacobian[[profile]]
       })))
}

.multilpa_chart_natural_jacobian <- function(object) {
  encoded <- .multilpa_chart_encode(object)
  d <- encoded$chart$d
  jacobian <- .multilpa_chart_map(encoded$values, encoded$chart, encoded$anchor,
                                  derivatives = TRUE)$jacobian
  rows <- if (.multilpa_spread_shared(object)) 1L else seq_len(object$n_profiles)
  keep <- if (.multilpa_is_ellipsoidal(object$covariance_structure)) {
    which(lower.tri(matrix(0, d, d), diag = TRUE))
  } else which(diag(d) == 1)
  do.call(rbind, lapply(rows, function(profile) {
    jacobian[[profile]][keep, , drop = FALSE]
  }))
}

.multilpa_step_ml_polish <- function(fit, values, variance) {
  objective <- function(parameters) {
    -.multilpa_step_ml_log_likelihood(fit, values, variance, parameters)
  }
  gradient <- function(parameters) {
    -colSums(.multilpa_step_ml_scores(fit, values, variance, parameters))
  }
  scale <- .multilpa_step_ml_scale(fit, variance)
  newton <- function(state, step) {
    if (isTRUE(state$done)) return(state)
    score <- gradient(state$parameters)
    if (max(abs(score * scale)) < 1e-9 * (1 + abs(state$value))) {
      return(c(state[c("parameters", "value")], list(done = TRUE)))
    }
    hessian <- .multilpa_step_ml_hessian(gradient, state$parameters, scale)
    # Solved on the coordinates' own scale, like the sandwich's inverse.
    direction <- tryCatch(scale * solve(hessian * tcrossprod(scale), score * scale),
                          error = function(condition) NULL)
    if (is.null(direction)) return(c(state[c("parameters", "value")], list(done = FALSE)))
    # Halve the step until the likelihood does not fall.
    candidates <- lapply(2^-(0:20), \(size) state$parameters - size * direction)
    values_at <- vapply(candidates, objective, numeric(1))
    accepted <- which(values_at <= state$value)[1L]
    if (is.na(accepted)) return(c(state[c("parameters", "value")], list(done = FALSE)))
    list(parameters = candidates[[accepted]], value = values_at[accepted], done = NA)
  }
  start <- .multilpa_step_ml_coordinates(fit, variance)
  state <- Reduce(newton, seq_len(25L),
                  init = list(parameters = start, value = objective(start), done = NA))
  classes <- length(fit$means)
  sds <- exp(state$parameters[-seq_len(classes)])
  fit$means <- unname(state$parameters[seq_len(classes)])
  fit$variances <- unname(if (identical(variance, "equal")) rep(sds^2, classes) else sds^2)
  fit$log_likelihood <- -state$value
  # Converged when EM met its tolerance or Newton found the score zero; a
  # Newton step that cannot improve on a converged EM estimate (the score
  # left is rounding) does not undo EM's convergence.
  fit$converged <- isTRUE(fit$converged) || isTRUE(state$done)
  fit$responsibilities <- .multilpa_step_ml_responsibilities(fit, values)
  fit
}

.multilpa_step_ml_responsibilities <- function(fit, values) {
  joint <- log(fit$weights) + vapply(seq_along(fit$means), function(class) {
    stats::dnorm(values, fit$means[class], sqrt(fit$variances[class]), log = TRUE)
  }, numeric(length(values)))
  largest <- apply(joint, 1L, max)
  exp(joint - largest - log(rowSums(exp(joint - largest))))
}

.multilpa_step_ml_coordinates <- function(fit, variance) {
  sds <- sqrt(fit$variances)
  c(fit$means, log(if (identical(variance, "equal")) sds[1L] else sds))
}

.multilpa_step_ml_scale <- function(fit, variance) {
  spread <- sqrt(mean(fit$variances))
  c(rep(spread, length(fit$means)),
    rep(1, if (identical(variance, "equal")) 1L else length(fit$means)))
}

.multilpa_step_ml_hessian <- function(gradient, parameters, scale) {
  steps <- 1e-5 * scale
  columns <- vapply(seq_along(parameters), function(j) {
    up <- parameters
    up[j] <- up[j] + steps[j]
    down <- parameters
    down[j] <- down[j] - steps[j]
    (gradient(up) - gradient(down)) / (2 * steps[j])
  }, numeric(length(parameters)))
  hessian <- matrix(columns, length(parameters))
  (hessian + t(hessian)) / 2
}

.multilpa_step_ml_log_likelihood <- function(fit, values, variance, parameters) {
  classes <- length(fit$means)
  means <- parameters[seq_len(classes)]
  sds <- exp(parameters[-seq_len(classes)])
  sds <- if (identical(variance, "equal")) rep(sds, classes) else sds
  joint <- log(fit$weights) + vapply(seq_len(classes), function(class) {
    stats::dnorm(values, means[class], sds[class], log = TRUE)
  }, numeric(length(values)))
  largest <- apply(joint, 1L, max)
  sum(largest + log(rowSums(exp(joint - largest))))
}

.multilpa_step_ml_influence <- function(fit, values, variance) {
  chart <- fit$outcome_coordinates
  outcome_scale <- if (is.null(chart)) 1 else chart$scale
  if (!is.null(chart)) {
    values <- (values - chart$center) / outcome_scale
    fit$means <- chart$means
    fit$variances <- fit$variances / outcome_scale^2
  }
  coordinates <- .multilpa_step_ml_coordinates(fit, variance)
  scale <- .multilpa_step_ml_scale(fit, variance)
  information <- .multilpa_step_ml_hessian(
    function(parameters) -colSums(.multilpa_step_ml_scores(fit, values, variance,
                                                          parameters)),
    coordinates, scale)
  # Inverted on the coordinates' own scale, D (D H D)^-1 D: in raw units the
  # means' and log standard deviations' information differ by the outcome's
  # units squared, and at 1e8 that alone made an identified model singular.
  inverse <- tryCatch({
    conditioned <- information * tcrossprod(scale)
    # A genuine saddle or unidentified class must not produce uncertainty
    # from an arbitrary invertible but nonpositive information matrix.
    chol(conditioned)
    solve(conditioned) * tcrossprod(scale)
  }, error = function(condition) {
    stop(errorCondition(
      "The information of the step-three model is singular; the class means are not identified.",
      class = "latents_singular_information", call = NULL))
  })
  scores <- .multilpa_step_ml_scores(fit, values, variance)
  outcome_scale * (scores %*% inverse)[, seq_along(fit$means), drop = FALSE]
}

.multilpa_level_assignments <- function(object, level) {
  stopifnot("`object` must be a fitted model of this package" =
              .multilpa_any_fit(object))
  level <- match.arg(level, c("individuals", "groups"))
  if (identical(level, "individuals")) {
    list(posteriors = object$subject_posteriors, modal = object$subject_profiles,
         units = seq_len(object$n_observations), group_index = object$group_index,
         n_classes = object$n_profiles)
  } else {
    list(posteriors = object$group_posteriors, modal = object$group_classes,
         units = object$group_values, group_index = seq_along(object$group_classes),
         n_classes = object$n_group_classes)
  }
}

.multilpa_check_three_step_fit <- function(object) {
  stopifnot("`x` must be a fitted model of this package" =
              .multilpa_any_fit(object))
  if (inherits(object, "multilpa_covariates")) {
    stop(errorCondition(paste(
      "Three-step correction is unavailable for a fit that already uses",
      "membership covariates: this method has no classification-error",
      "adjustment conditional on those covariates. Fit the measurement model",
      "without membership covariates before using three_step() or r3step()."),
      class = "latents_unsupported_three_step", call = NULL))
  }
  invisible(NULL)
}

.multilpa_error_matrix <- function(pieces) {
  classes <- seq_len(pieces$n_classes)
  totals <- colSums(pieces$posteriors)
  ## vapply() drops to a vector when there is only one class, so the shape is
  ## forced; a one-class model is degenerate but must not error here.
  result <- matrix(vapply(classes, function(assigned) {
    colSums(pieces$posteriors * (pieces$modal == assigned)) / totals
  }, numeric(pieces$n_classes)), nrow = pieces$n_classes,
  dimnames = list(paste0("true_", classes), paste0("assigned_", classes)))
  result
}

.multilpa_invert_errors <- function(errors) {
  inverse <- tryCatch(solve(errors), error = function(condition) {
    stop(errorCondition(
      paste("The classification error matrix cannot be inverted, so the classes",
            "are not separated well enough for a three-step correction.",
            "Inspect get_results(x, \"classification_errors\")."),
      class = "latents_inseparable_classes", call = NULL))
  })
  if (min(abs(eigen(as.matrix(errors), only.values = TRUE)$values)) < 1e-8) {
    stop(errorCondition(
      "The classification error matrix is numerically singular; the classes are not separable.",
      class = "latents_inseparable_classes", call = NULL))
  }
  inverse
}

.multilpa_step_clusters <- function(influence, pieces, vcov_type) {
  units <- if (identical(vcov_type, "cluster")) {
    pieces$group_index
  } else seq_len(nrow(influence))
  clustered <- rowsum(influence, units, reorder = FALSE)
  .multilpa_require_clusters(
    nrow(clustered), pieces$n_classes,
    what = "A cluster-robust standard error for the class outcome means",
    unit = if (identical(vcov_type, "cluster")) "independent groups" else "observations",
    alternative = if (identical(vcov_type, "cluster")) {
      paste("`vcov_type = \"independent\"` treats every observation as its own",
            "unit instead, which ignores the nesting and must be reported as",
            "having done so.")
    })
  clustered * sqrt(.inference_cluster_factor(nrow(clustered)))
}

.multilpa_outcome_values <- function(object, data, outcome, level) {
  values <- data[[outcome]]
  .multilpa_check_row_count(object, data)
  if (identical(level, "individuals")) return(values)
  by_group <- split(values, object$group_index)
  constant <- vapply(by_group, function(v) length(unique(v)) == 1L, logical(1))
  if (!all(constant)) {
    stop(errorCondition(
      "For `level = \"groups\"` the outcome must be constant within each group.",
      class = "latents_bad_outcome", call = NULL))
  }
  vapply(by_group, function(v) v[[1L]], numeric(1))
}

.multilpa_step_weights <- function(pieces, method) {
  classes <- seq_len(pieces$n_classes)
  switch(method,
    bch = {
      inverse <- .multilpa_invert_errors(.multilpa_error_matrix(pieces))
      inverse[pieces$modal, , drop = FALSE]
    },
    proportional = pieces$posteriors,
    modal = vapply(classes, function(class) as.numeric(pieces$modal == class),
                   numeric(length(pieces$modal))))
}

.multilpa_logit_prior <- function(gamma, design) {
  eta <- cbind(design %*% gamma, 0)
  scaled <- exp(eta - apply(eta, 1L, max))
  scaled / rowSums(scaled)
}

.r3step_require_classes <- function(pieces) {
  if (pieces$n_classes < 2L) {
    stop(errorCondition(
      "A single class has no membership to predict.",
      class = "latents_inseparable_classes", call = NULL))
  }
  invisible(NULL)
}

.r3step_transitions <- function(x, data, covariates, level, ci_level, vcov_type,
                                adjust, by_group_class, initial_covariates,
                                transition_covariates) {
  bad_argument <- function(message) {
    stop(errorCondition(message, class = "latents_bad_argument", call = NULL))
  }
  if (!inherits(x, c("multilpa_transitions", "multilpa_lta"))) {
    bad_argument(paste(
      "`initial_covariates` and `transition_covariates` apply to a transition",
      "model fitted by lta(); for profile membership use `covariates`."))
  }
  if (length(covariates) > 0L || !identical(level, "individuals") || by_group_class) {
    bad_argument(paste(
      "A three-step transition model takes `initial_covariates` and",
      "`transition_covariates` only: not `covariates`, `level` or",
      "`by_group_class`."))
  }
  if (.latents_is_weighted(x)) .latents_refuse_weights("`r3step()` yet")
  named <- function(value) is.character(value) && !anyNA(value) && !anyDuplicated(value)
  stopifnot(
    "`data` must be a data frame" = is.data.frame(data),
    "`initial_covariates` must be distinct column names of `data`" =
      named(initial_covariates) && all(initial_covariates %in% names(data)),
    "`transition_covariates` must be distinct column names of `data`" =
      named(transition_covariates) && all(transition_covariates %in% names(data)),
    "`ci_level` must be a single number in (0, 1)" =
      is.numeric(ci_level) && length(ci_level) == 1L && ci_level > 0 && ci_level < 1)
  .lta_three_step(x, data, initial_covariates, transition_covariates, ci_level,
                  vcov_type, adjust)
}

.multilpa_r3step_design <- function(object, data, covariates, level) {
  .multilpa_check_row_count(object, data)
  values <- data[covariates]
  if (identical(level, "groups")) {
    constant <- vapply(values, function(column) {
      all(vapply(split(column, object$group_index),
                 function(v) length(unique(v)) == 1L, logical(1)))
    }, logical(1))
    if (!all(constant)) {
      stop(errorCondition(
        "For `level = \"groups\"` every covariate must be constant within a group.",
        class = "latents_bad_covariate", call = NULL))
    }
    values <- values[!duplicated(object$group_index), , drop = FALSE]
  }
  .multilpa_r3step_check_rank(cbind(`(Intercept)` = 1, as.matrix(values)))
}

.multilpa_r3step_check_rank <- function(design) {
  if (qr(sweep(design, 2L, .multilpa_design_scale(design), "/"))$rank < ncol(design)) {
    stop(errorCondition(
      "The covariate design is rank deficient; remove constant or collinear predictors.",
      class = "latents_bad_covariate", call = NULL))
  }
  design
}

.multilpa_measured_items <- function(x) {
  unique(c(x$vars, x$original_vars))
}

.trajectory_view <- function(x) {
  growth <- inherits(x, "latents_growth_mixture")
  if (!growth && !(inherits(x, "latents_mixture_regression") &&
                   identical(x$spec$nesting, "group"))) {
    stop(errorCondition(paste(
      "Trajectory views need persons as the classified units: fit with `id`",
      "and `class_level = \"group\"`."), class = "latents_bad_argument", call = NULL))
  }
  spec <- x$spec
  posterior <- if (growth) x$expectation$posterior else x$expectation$group_tau
  family <- spec$family %||% "gaussian"
  inverse_link <- switch(family, gaussian = identity, binomial = stats::plogis,
                         poisson = exp, negative_binomial = exp)
  response_mean <- if (identical(family, "ordinal")) {
    function(linear, classes) {
      scores <- .ordinal_expected_scores(
        matrix(linear, length(linear), spec$n_classes), x$params$thresholds)
      scores[cbind(seq_along(linear), classes)]
    }
  } else function(linear, classes) inverse_link(linear)
  list(growth = growth, spec = spec, posterior = posterior,
       modal = max.col(posterior, ties.method = "first"),
       classes = paste0("class_", seq_len(spec$n_classes)), family = family,
       inverse_link = inverse_link, response_mean = response_mean,
       weights = spec$sampling_weights)
}

.trajectory_inference <- function(x, vcov_type = NULL) {
  if (inherits(x, "latents_growth_mixture")) .growth_resolve_inference(x, vcov_type) else
    .mixture_resolve_inference(x, vcov_type)
}

.trajectory_observed <- function(view) {
  if (identical(view$family, "binomial")) view$spec$y / view$spec$trials else view$spec$y
}

.trajectory_band <- function(x, rows, inference, level) {
  view <- .trajectory_view(x)
  spec <- view$spec
  design <- .growth_design(x, rows)
  z <- .inference_critical(level, "one_minus")
  if (identical(view$family, "ordinal")) {
    return(.ordinal_trajectory_band(x, design, inference, z, view$classes))
  }
  do.call(rbind, lapply(view$classes, function(class) {
    names <- c(sprintf("coefficient.%s.%s", class, colnames(spec$x)),
               if (ncol(spec$z) > 0L) sprintf("coefficient.common.%s", colnames(spec$z)))
    estimate <- as.vector(design %*% inference$theta[names]) + attr(design, "offset")
    covariance <- inference$vcov[names, names, drop = FALSE]
    std_error <- .inference_delta_se(design, covariance, "rowsums")
    response <- view$inverse_link(estimate)
    response_derivative <- switch(view$family, gaussian = rep(1, length(estimate)),
                                  binomial = response * (1 - response),
                                  poisson = , negative_binomial = response)
    data.frame(class = class, estimate = response,
               std_error = std_error * response_derivative,
               conf_low = view$inverse_link(estimate - z * std_error),
               conf_high = view$inverse_link(estimate + z * std_error),
               stringsAsFactors = FALSE)
  }))
}

.trajectory_is_fit <- function(x) {
  inherits(x, "latents_growth_mixture") ||
    (inherits(x, "latents_mixture_regression") && identical(x$spec$nesting, "group"))
}

.trajectory_check_three_step <- function(x, data) {
  view <- .trajectory_view(x)
  spec <- view$spec
  if (!is.null(spec$cluster)) {
    stop(errorCondition(paste(
      "Three-step correction is unavailable for a multilevel growth mixture:",
      "its persons are dependent within clusters, and the correction treats",
      "them as independent."), class = "latents_unsupported_three_step", call = NULL))
  }
  if (!spec$intercept_only) {
    stop(errorCondition(paste(
      "Three-step correction is unavailable for a fit that already uses",
      "membership covariates: it has no classification-error adjustment",
      "conditional on them. Fit the trajectory model without `membership`."),
      class = "latents_unsupported_three_step", call = NULL))
  }
  .trajectory_check_data(x, data)
  view
}

.trajectory_check_data <- function(x, data) {
  spec <- x$spec
  if (!is.data.frame(data) || !spec$id %in% names(data) ||
      nrow(data) < max(spec$kept_rows) ||
      !.multilpa_same_values(data[[spec$id]][spec$kept_rows], spec$model_data[[spec$id]])) {
    stop(errorCondition(
      "`data` must be the data frame the trajectory model was fitted to.",
      class = "latents_bad_inference_data", call = NULL))
  }
  invisible(NULL)
}

.trajectory_pieces <- function(view) {
  list(posteriors = view$posterior, modal = view$modal,
       units = view$spec$group_levels, group_index = seq_len(view$spec$n_groups),
       n_classes = view$spec$n_classes)
}

.trajectory_uses <- function(spec, variable) {
  identical(variable, spec$response_name) ||
    variable %in% all.vars(stats::delete.response(spec$terms))
}

.trajectory_three_step_inputs <- function(x, data, outcome) {
  view <- .trajectory_check_three_step(x, data)
  spec <- view$spec
  if (.trajectory_uses(spec, outcome)) {
    stop(errorCondition(sprintf(
      "`%s` is part of the trajectory model, so it is not a distal outcome.",
      outcome), class = c("multilpa_indicator_reused", "latents_bad_outcome"),
      call = NULL))
  }
  by_person <- split(data[[outcome]][spec$kept_rows], spec$group_index)
  constant <- vapply(by_person, function(v) length(unique(v)) == 1L, logical(1))
  if (!all(constant)) {
    stop(errorCondition(sprintf(paste(
      "`%s` varies within persons; a distal outcome of a trajectory model is",
      "one value per person."), outcome),
      class = "latents_bad_outcome", call = NULL))
  }
  list(pieces = .trajectory_pieces(view),
       values = vapply(by_person, function(v) v[[1L]], numeric(1), USE.NAMES = FALSE))
}

.trajectory_r3step_inputs <- function(x, data, covariates) {
  view <- .trajectory_check_three_step(x, data)
  spec <- view$spec
  reused <- covariates[vapply(covariates, .trajectory_uses, logical(1), spec = spec)]
  if (length(reused) > 0L) {
    stop(errorCondition(sprintf(
      "%s already part of the trajectory model, so not an external predictor.",
      paste(sprintf("`%s` is", reused), collapse = ", ")),
      class = c("multilpa_indicator_reused", "latents_bad_covariate"), call = NULL))
  }
  values <- vapply(covariates, function(covariate) {
    by_person <- split(data[[covariate]][spec$kept_rows], spec$group_index)
    if (!all(vapply(by_person, function(v) length(unique(v)) == 1L, logical(1)))) {
      stop(errorCondition(sprintf(paste(
        "`%s` varies within persons; a covariate of trajectory class",
        "membership is one value per person."), covariate),
        class = "latents_bad_covariate", call = NULL))
    }
    vapply(by_person, function(v) v[[1L]], numeric(1), USE.NAMES = FALSE)
  }, numeric(spec$n_groups)) |> matrix(spec$n_groups, length(covariates))
  colnames(values) <- covariates
  list(pieces = .trajectory_pieces(view),
       design = .multilpa_r3step_check_rank(cbind(`(Intercept)` = 1, values)))
}

.multilpa_transition_encode <- function(x, scale, centers = NULL) {
  view <- .multilpa_transition_view(x, centers)
  raw <- .multilpa_coefficients_raw(view, scale)
  blocks <- .multilpa_transition_shared_blocks(view, scale)
  n_profiles <- x$n_profiles
  n_types <- x$n_group_classes
  natural <- identical(scale, "natural")
  kept <- if (natural) seq_len(n_profiles) else seq_len(n_profiles - 1L)
  contrast <- function(probabilities) {
    if (natural) probabilities[kept] else
      log(probabilities[kept]) - log(probabilities[n_profiles])
  }
  initial <- unlist(lapply(seq_len(n_types), function(type) {
    stats::setNames(contrast(x$initial_probabilities[type, ]),
                    sprintf("%s[%d,%d]", if (natural) "initial_probability" else
                      "initial_logit", type, kept))
  }))
  transition <- unlist(lapply(seq_len(n_types), function(type) {
    unlist(lapply(seq_len(n_profiles), function(from) {
      stats::setNames(
        contrast(x$transition_probabilities[from, , type]),
        sprintf("%s[%d,%d,%d]", if (natural) "transition_probability" else
          "transition_logit", type, from, kept))
    }))
  }))
  c(raw[c(blocks$measurement, blocks$group)], initial, transition)
}

.multilpa_transition_decode <- function(theta, view, n_measurement, n_group) {
  n_profiles <- view$n_profiles
  n_types <- view$n_group_classes
  n_free <- n_profiles - 1L
  measurement <- theta[seq_len(n_measurement)]
  group <- theta[n_measurement + seq_len(n_group)]
  initial <- theta[n_measurement + n_group + seq_len(n_types * n_free)]
  transition <- theta[n_measurement + n_group + n_types * n_free +
                        seq_len(n_types * n_profiles * n_free)]
  ## The cross-sectional decoder rebuilds the measurement and the group shares;
  ## the profile block it expects is filled with zeros and discarded.
  parameters <- .multilpa_decode(c(measurement, numeric(n_types * n_free), group),
                                 view)
  parameters$profile_probabilities <- NULL
  softmax <- function(logits) {
    full <- c(logits, 0)
    exp(full - .multilpa_log_sum_exp(matrix(full, 1L)))
  }
  parameters$initial_probabilities <- t(matrix(vapply(seq_len(n_types), function(type) {
    softmax(initial[(type - 1L) * n_free + seq_len(n_free)])
  }, numeric(n_profiles)), n_profiles, n_types))
  parameters$transition_probabilities <- array(vapply(seq_len(n_types), function(type) {
    rows <- vapply(seq_len(n_profiles), function(from) {
      at <- ((type - 1L) * n_profiles + from - 1L) * n_free
      softmax(transition[at + seq_len(n_free)])
    }, numeric(n_profiles))
    t(rows)
  }, numeric(n_profiles * n_profiles)), c(n_profiles, n_profiles, n_types))
  parameters
}

.multilpa_transition_group_counts <- function(x, layout, parameters, codes,
                                              group_posteriors) {
  n_profiles <- nrow(parameters$means)
  n_groups <- nrow(layout$slot)
  log_density <- if (ncol(x) > 0L) {
    .multilpa_gaussian_moments(x, parameters)$log_density
  } else matrix(0, nrow(x), n_profiles)
  if (!is.null(codes)) {
    log_density <- log_density +
      .multilpa_categorical_log_density(codes, parameters$response_probabilities)
  }
  emission <- .multilpa_sequence_emission(log_density, layout)$log_density
  origin <- rep(seq_len(n_profiles), times = n_profiles)
  destination <- rep(seq_len(n_profiles), each = n_profiles)
  per_type <- lapply(seq_len(ncol(group_posteriors)), function(type) {
    transition <- matrix(parameters$transition_probabilities[, , type],
                         n_profiles, n_profiles)
    pass <- .multilpa_forward_backward(emission, layout,
                                       parameters$initial_probabilities[type, ],
                                       transition)
    weights <- group_posteriors[, type]
    initial <- exp(pass$alpha[[1L]] + pass$beta[[1L]] - pass$log_scaled) * weights
    log_transition <- rep(log(transition), each = n_groups)
    moves <- if (layout$n_occasions < 2L) {
      matrix(0, n_groups, n_profiles * n_profiles)
    } else Reduce(`+`, lapply(seq_len(layout$n_occasions)[-1L], function(occasion) {
      active <- weights * layout$within[, occasion]
      log_from <- pass$alpha[[occasion - 1L]] - pass$log_scaled
      log_to <- pass$beta[[occasion]] + emission[[occasion]]
      joint <- log_from[, origin, drop = FALSE] + log_to[, destination, drop = FALSE] +
        log_transition
      active * exp(joint)
    }))
    list(initial = initial, transition = moves)
  })
  list(initial = lapply(per_type, `[[`, "initial"),
       transition = lapply(per_type, `[[`, "transition"))
}

.multilpa_check_transition_regularity <- function(x, vcov_type) {
  refuse <- function(message, class) {
    stop(errorCondition(message, class = class, call = NULL))
  }
  if (!isTRUE(x$converged)) {
    refuse("Inference requires a converged fit.", "latents_no_converge")
  }
  if (!is.null(x$covariance_structure) &&
      !x$covariance_structure %in% c("EEI", "VVI", "EEE", "VVV")) {
    refuse(paste(
      "Standard errors for transition models are available for the EEI, VVI,",
      "EEE and VVV structures; this fit uses", x$covariance_structure, "."),
      "latents_unsupported_inference")
  }
  n_groups <- sum(.multilpa_inference_groups(x, observed_only = TRUE))
  if (vcov_type %in% c("robust", "opg") && n_groups <= x$n_parameters) {
    refuse(sprintf(paste(
      "Robust and OPG inference need more groups than parameters; this fit has",
      "%d groups and %d parameters."), n_groups, x$n_parameters),
      "latents_too_few_groups")
  }
  if (isTRUE(x$boundary)) {
    refuse("Wald inference is unavailable for a bound-active fit.",
           "latents_boundary_fit")
  }
  if (any(x$empty_transition_rows)) {
    refuse(paste(
      "A transition row was never informed: some profile is occupied by no",
      "group before its last occasion, so its outgoing probabilities are not",
      "estimated and have no standard error."), "latents_boundary_fit")
  }
  floor <- .multilpa_probability_floor(x)
  probabilities <- c(unlist(x$response_probabilities, use.names = FALSE),
                     x$initial_probabilities, x$transition_probabilities,
                     x$group_probabilities)
  if (any(probabilities <= floor)) {
    refuse(paste(
      "Wald inference is unavailable when a probability sits at its lower",
      "bound: its logit is at minus infinity, where the likelihood has no",
      "curvature to invert."), "latents_boundary_fit")
  }
  invisible(NULL)
}

.multilpa_check_transition_data <- function(x, data) {
  continuous <- .multilpa_continuous_names(x)
  same <- function(left, right) identical(unname(left), unname(right))
  ok <- is.data.frame(data) && nrow(data) == x$n_observations &&
    all(c(x$vars, x$id, x$time) %in% names(data)) &&
    identical(match(data[[x$id]], x$group_values), x$group_index) &&
    (length(continuous) == 0L ||
       same(as.matrix(data[continuous]), x$indicator_data))
  if (ok && length(x$categorical %||% character()) > 0L) {
    encoded <- .multilpa_encode_categorical(data[x$categorical])
    ok <- same(encoded$codes, x$categorical_data) &&
      identical(encoded$levels, x$categorical_levels)
  }
  if (ok) ok <- identical(.multilpa_time_values(data, x$time, x$id, x$vars), x$time_values)
  if (!ok) {
    stop(errorCondition(
      "`data` must reproduce the indicators, categories, groups, occasions and row order of the fit.",
      class = "latents_bad_inference_data", call = NULL))
  }
  invisible(NULL)
}

confint.multilpa_transitions <- function(object, parm, level = 0.95, data = NULL,
                                         ...) {
  inference <- parameter_inference(object, data = data, level = level, ...)
  names_used <- .multilpa_parameter_names(inference)
  bounds <- cbind(inference$conf_low, inference$conf_high)
  dimnames(bounds) <- list(names_used, paste0(
    format(100 * c((1 - level) / 2, (1 + level) / 2), trim = TRUE), " %"))
  if (missing(parm)) return(bounds)
  bounds[parm, , drop = FALSE]
}

