.gg_spread <- function(y, gap) {
  if (length(y) < 2L) return(y)
  ordering <- order(y)
  steps <- gap * (seq_along(y) - 1)
  spread <- cummax(y[ordering] - steps) + steps
  spread <- spread - mean(spread) + mean(y)
  out <- numeric(length(y))
  out[ordering] <- spread
  out
}

.gg_ink <- function(fills) {
  if (length(fills) == 0L) return(character())
  rgb <- grDevices::col2rgb(fills)
  luminance <- 0.299 * rgb[1L, ] + 0.587 * rgb[2L, ] + 0.114 * rgb[3L, ]
  ifelse(luminance > 150, "grey10", "white")
}

.gg_probability_fill <- function(values) {
  ramp <- grDevices::colorRamp(c("#FFFFFF", "#0072B2"))
  inside <- pmin(pmax(values, 0), 1)
  inside[is.na(inside)] <- 0
  grDevices::rgb(ramp(inside), maxColorValue = 255)
}

.gg_group_class_text <- function(x) {
  if (isTRUE(x$n_group_classes > 1L)) {
    sprintf(", %d group classes", x$n_group_classes)
  } else ""
}

.gg_category_scores <- function(blocks) {
  stopifnot(is.list(blocks))
  lapply(names(blocks), function(indicator) {
    block <- blocks[[indicator]]
    scores <- withCallingHandlers(as.numeric(colnames(block)), warning = function(w) {
      invokeRestart("muffleWarning")
    })
    if (length(scores) != ncol(block) || any(!is.finite(scores)) ||
        anyDuplicated(scores)) {
      stop(errorCondition(sprintf(
        paste("Categorical profile summaries need distinct finite numeric category",
              "labels; `%s` does not have them. Use `what = \"responses\"` instead."),
        indicator), class = "latents_bad_argument", call = NULL))
    }
    scores
  })
}

.gg_match_bounds <- function(errors, parameter, profile, term) {
  stopifnot(length(profile) == length(term))
  if (is.null(errors)) {
    return(data.frame(lower = rep(NA_real_, length(profile)),
                      upper = rep(NA_real_, length(profile))))
  }
  wanted <- errors[errors$parameter == parameter, , drop = FALSE]
  at <- match(paste(profile, term, sep = "\r"),
              paste(sub("^profile_", "", wanted$outcome), wanted$term,
                    sep = "\r"))
  data.frame(lower = wanted$conf_low[at], upper = wanted$conf_high[at])
}

.gg_undrawn_caption <- function(x, drawn) {
  stopifnot(is.character(drawn))
  kinds <- list(
    list(vars = x$categorical, text = "categorical %s (what = \"responses\")"),
    list(vars = x$ordinal, text = "ordinal %s (get_results(fit, \"ordinal\"))"),
    list(vars = x$count, text = "count %s (get_results(fit, \"counts\"))"))
  parts <- vapply(kinds, \(kind) {
    missing_vars <- setdiff(as.character(kind$vars), drawn)
    if (length(missing_vars) == 0L) return(NA_character_)
    sprintf(kind$text, paste(missing_vars, collapse = ", "))
  }, character(1))
  parts <- parts[!is.na(parts)]
  if (length(parts) == 0L) return(NULL)
  sprintf("Not drawn: %s.", paste(parts, collapse = "; "))
}

.gg_has_group_classes <- function(x) {
  is.matrix(x$group_posteriors) && ncol(x$group_posteriors) >= 2L
}

.gg_capitalize <- function(text) {
