        .multilpa_sequences(x, format = match.arg(format)),
      "format"),
    sequence_summary = .multilpa_table(.multilpa_sequence_summary))
  if (!inherits(x, "multilpa_transitions")) return(shared)
  c(shared,
    list(sequence_lengths = .multilpa_table(.multilpa_sequence_length_frame)))
}

.multilpa_hide_fabricated_id <- function(x, frame) {
  if (!isTRUE(x$single_level) || !x$id %in% names(frame)) return(frame)
  frame[setdiff(names(frame), x$id)]
}

.multilpa_default_level <- function(x, level) {
  if (!is.null(level)) return(level)
  if (is.null(x$group_posteriors)) "individuals" else "both"
}

.multilpa_diagnostic_residuals <- function(x) {
  if (!is.null(x$residuals)) return(x$residuals)
  if (isTRUE(x$fit$noise)) {
    stop(errorCondition(paste(
      "This fit has no bivariate residuals: they do not account for a noise",
      "component yet."),
      class = "latents_unsupported_noise", call = NULL))
  }
  stop(errorCondition(
    "This fit has no bivariate residuals: they need a discrete group-class model.",
    class = "latents_no_group_classes", call = NULL))
}

.multilpa_print_tables <- function(tables, rows = 10L, digits = 4L) {
  stopifnot(
    "`rows` must be a single non-negative whole number" =
      is.numeric(rows) && length(rows) == 1L && is.finite(rows) && rows >= 0 &&
      rows == as.integer(rows),
    "the tables must be a named list of data frames" =
      is.list(tables) && !is.null(names(tables)))
  invisible(lapply(names(tables), function(name) {
    frame <- tables[[name]]
    cat(sprintf("\n-- %s %s\n", name,
                strrep("-", max(3L, 64L - nchar(name)))))
    if (nrow(frame) == 0L) {
      cat("   (no rows)\n")
      return(invisible(NULL))
    }
    # `rows = 0` asks for the headings alone; printing a zero-row head would
    # dump the column names as if the table were empty.
    if (rows > 0) print(utils::head(frame, rows), digits = digits, row.names = FALSE)
    if (nrow(frame) > rows) {
      cat(sprintf("   ... %d more rows.  get_results(x, what = \"%s\")\n",
                  nrow(frame) - rows, name))
    }
    invisible(NULL)
  }))
}

.multilpa_print_primary <- function(x, rows = 20L) {
  stopifnot("`rows` must be a single non-negative whole number" =
              is.numeric(rows) && length(rows) == 1L && is.finite(rows) &&
              rows >= 0 && rows == as.integer(rows))
  name <- names(.multilpa_catalogue(x))[1L]
  # Printing shows the estimates; the standard errors belong to the tables
  # asked for by name, and computing them on every print would be slow.
  table <- if (identical(name, "profiles")) .multilpa_profile_frame(x) else
    get_results(x)
  ## The Gaussian measurement is printed one row per profile. Everything else
  ## keeps the catalogue's own shape, which is already one row per thing.
  if (identical(name, "profiles") && nrow(table) > 0L) {
    wide <- .multilpa_wide_means(x)
    ## How big each profile is belongs beside what it looks like: a mean is read
    ## differently when it describes two percent of the sample. Matched on the
    ## class label rather than on row order, which the two tables need not share.
    sizes <- .multilpa_count_frame(x)
    individuals <- sizes[sizes$level == "individuals", , drop = FALSE]
    at <- match(wide$profile, individuals$class)
    wide$count <- individuals$effective_count[at]
    wide$proportion <- individuals$effective_proportion[at]
    cat("\n")
    if (rows > 0) print(utils::head(wide, rows), row.names = FALSE)
    if (nrow(wide) > rows) {
      cat(sprintf("   ... %d more profiles.\n", nrow(wide) - rows))
    }
    cat("\nVariances and standard errors: get_results(x, \"profiles\").",
        "\nEvery other table: get_results(x, what = ), or get_results(x, \"all\").\n")
    return(invisible(NULL))
  }
  if (nrow(table) == 0L && length(x$categorical %||% character()) > 0L) {
    table <- .multilpa_response_frame(x)
    name <- "responses"
  }
  if (nrow(table) == 0L) return(invisible(NULL))
  cat("\n")
  if (rows > 0) print(utils::head(table, rows), row.names = FALSE)
  if (nrow(table) > rows) {
    cat(sprintf("   ... %d more rows.  get_results(x, \"%s\")\n",
                nrow(table) - rows, name))
  }
  cat("\nEvery other table: get_results(x, what = ), or get_results(x, \"all\").\n")
  invisible(NULL)
}

.latents_grid_kind <- function(x) {
  kinds <- c(multilpa_enumeration = "profiles",
             latents_transition_enumeration = "transitions",
             latents_family_enumeration = "families",
             latents_regression_enumeration = "regressions")
  at <- inherits(x, names(kinds), which = TRUE)
  if (!any(at > 0L)) return(NA_character_)
  unname(kinds[which(at > 0L)[1L]])
}

.latents_grid_view_names <- function() {
  c("entropy", "avepp", "diagnostics", .latents_selection_views(), "selection",
    "tree")
}

.latents_refuse_non_grid <- function(x, verb) {
  stop(errorCondition(sprintf(paste(
    "%s() takes an enumeration grid from enumerate_classes(), enumerate_lpa(),",
    "enumerate_lca() or enumerate_regressions(), not a `%s` object."),
    verb, class(x)[1L]), class = "latents_bad_argument", call = NULL))
}

.latents_grid_offer_text <- function(views) {
  paste(sprintf("\"%s\"", c(unname(views$criteria), "all", views$views)),
        collapse = ", ")
}

.latents_require_grid_views <- function(x, what, verb) {
  views <- .latents_grid_views(x, verb)
  refused <- intersect(what, names(views$refused))
  if (length(refused) == 0L) return(invisible(NULL))
  stop(errorCondition(sprintf(
    "%s() cannot draw `what = \"%s\"` for a `%s` grid: %s. This grid offers %s.",
    verb, refused[1L], class(x)[1L], views$refused[[refused[1L]]],
    .latents_grid_offer_text(views)),
    class = c("latents_unsupported_view", "latents_bad_argument"), call = NULL))
}

.latents_grid_table <- function(x) {
  kind <- .latents_grid_kind(x)
  if (!identical(kind, "regressions")) {
    table <- .latents_named_table(x)
    table$converged <- table$converged %in% TRUE
    return(table)
  }
  table <- .subset2(x, "table")
  single_level <- all(table$n_group_classes %in% 1L)
  candidate <- paste0("classes", table$n_classes,
                      if (single_level) "" else paste0("_groups", table$n_group_classes))
  data.frame(
    candidate = candidate, n_profiles = as.integer(table$n_classes),
    n_group_classes = as.integer(table$n_group_classes), model = NA_character_,
    table[setdiff(names(table), c("n_classes", "n_group_classes", "converged"))],
    converged = table$converged %in% TRUE, boundary = NA,
    stringsAsFactors = FALSE)
}

.latents_regression_posteriors <- function(fit, level) {
  if (inherits(fit, "condition") || is.null(fit)) return(NULL)
  expectation <- fit$expectation
  if (inherits(fit, "latents_growth_mixture")) {
    if (identical(level, "groups")) return(expectation$structure$rho)
    return(expectation$posterior)
  }
  if (identical(level, "groups")) {
    return(if (identical(fit$spec$nesting, "two-level")) expectation$rho)
  }
  if (identical(fit$spec$nesting, "group")) expectation$group_tau else
    expectation$tau
}

.latents_grid_quality_table <- function(x, cutoff = 0.8) {
  kind <- .latents_grid_kind(x)
  if (identical(kind, "profiles")) return(.multilpa_enumeration_grid(x, cutoff))
  stopifnot("`cutoff` must be a single number between 0 and 1" =
              is.numeric(cutoff) && length(cutoff) == 1L && is.finite(cutoff) &&
              cutoff > 0 && cutoff <= 1)
  grid <- .latents_grid_table(x)
  fits <- unname(.subset2(x, "fits"))
  posteriors_of <- function(level) {
    lapply(fits, function(fit) {
      if (is.null(fit) || inherits(fit, "condition")) return(NULL)
      if (identical(kind, "regressions")) {
        return(.latents_regression_posteriors(fit, level))
      }
      if (identical(level, "groups")) .multilpa_classified_group_posteriors(fit) else
        .multilpa_classified_posteriors(fit)
    })
  }
  entropy_of <- function(posteriors) {
    vapply(posteriors, function(p) {
      if (is.null(p)) NA_real_ else .multilpa_relative_entropy(p)
    }, numeric(1))
  }
  lowest_avepp <- function(posteriors) {
    vapply(posteriors, function(p) {
      .multilpa_avepp_summary(p, cutoff)[["min"]]
    }, numeric(1))
  }
  individuals <- posteriors_of("individuals")
  groups <- posteriors_of("groups")
  # The tables already carry the entropy their own fits report: a family
  # grid's is its group classes', the others' their individuals'.
  grid$profile_entropy <- switch(kind, families = NA_real_, grid$entropy)
  grid$group_entropy <- switch(kind, families = grid$entropy, entropy_of(groups))
  grid$avepp_min <- lowest_avepp(individuals)
  grid$group_avepp_min <- lowest_avepp(groups)
  grid
}

.latents_grid_criteria_titles <- function(x, grid, criterion) {
  views <- .latents_grid_views(x)
  if (identical(views$kind, "profiles")) {
    return(.multilpa_distinct_criteria(grid, criterion))
  }
  repeats <- vapply(seq_along(criterion), function(index) {
    any(vapply(criterion[seq_len(index - 1L)], function(earlier) {
      isTRUE(all.equal(grid[[earlier]], grid[[criterion[index]]]))
    }, logical(1)))
  }, logical(1))
  kept <- criterion[!repeats]
  stats::setNames(kept, names(views$criteria)[match(kept, views$criteria)])
}

.latents_grid_smallest_shares <- function(x) {
  if (identical(.latents_grid_kind(x), "regressions")) {
    table <- .subset2(x, "table")
    return(list(individuals = ifelse(table$n_classes >= 2L, table$smallest_share,
                                     NA_real_),
                groups = rep(NA_real_, nrow(table))))
  }
  counts_field <- c(individuals = "effective_profile_counts",
                    groups = "effective_group_counts")
  share <- function(fit, level) {
    # The rows and groups the fit counts (see `drop_empty`).
    posteriors <- if (identical(level, "individuals"))
      .multilpa_classified_posteriors(fit) else .multilpa_classified_group_posteriors(fit)
    if (is.null(posteriors)) return(NA_real_)
    weights <- .multilpa_level_weights(fit, level, nrow(posteriors)) %||% 1
    counts <- fit[[counts_field[[level]]]] %||%
      colSums(posteriors[, seq_len(if (identical(level, "individuals"))
        ncol(fit$subject_posteriors) else ncol(posteriors)), drop = FALSE] * weights)
    if (length(counts) < 2L) return(NA_real_)
    min(counts) / sum(posteriors * weights)
  }
  fits <- .subset2(x, "fits")
  lapply(stats::setNames(names(counts_field), names(counts_field)), function(level) {
    vapply(fits, function(fit) {
      if (is.null(fit)) NA_real_ else share(fit, level)
    }, numeric(1L), USE.NAMES = FALSE)
  })
}

.latents_table <- function(table, level = NULL, title = NULL, display = NULL) {
  stopifnot("a result table must be a data frame" = is.data.frame(table))
  row.names(table) <- NULL
  attr(table, "level") <- level
  attr(table, "title") <- title
  attr(table, "display") <- display
  class(table) <- c("latents_table", setdiff(class(table), "latents_table"))
  table
}

.latents_column <- function(label, column, format = "number", decimals_from = NULL) {
  list(label = label, column = column, format = format, decimals_from = decimals_from)
}

.latents_column_decimals <- function(values) {
  finite <- abs(values[is.finite(values) & values != 0])
  smallest <- if (length(finite) > 0L) min(finite) else NA_real_
  if (!is.finite(smallest) || smallest >= 0.1) return(2L)
  if (smallest >= 0.01) return(3L)
  4L
}

.latents_format_p <- function(p) {
  ifelse(is.na(p), "", ifelse(p < 0.001, "<.001", sub("^0", "", sprintf("%.3f", p))))
}

.latents_cells <- function(x, spec) {
  values <- x[[spec$column[1L]]]
  fixed <- function(v, decimals) {
    ifelse(is.na(v), "", formatC(v, format = "f", digits = decimals))
  }
  switch(spec$format,
    text = ifelse(is.na(values), "", as.character(values)),
    label = .latents_label(values),
    integer = ifelse(is.na(values), "", format(round(values), trim = TRUE)),
    number = {
      finite <- values[is.finite(values)]
      if (length(finite) > 0L && all(abs(finite - round(finite)) < 1e-9)) {
        ifelse(is.na(values), "", format(round(values), trim = TRUE))
      } else {
        large <- length(finite) > 0L && max(abs(finite)) >= 100
        fixed(values, if (large) 2L else .latents_column_decimals(values))
      }
    },
    share = fixed(values, 3L),
    percent = ifelse(is.na(values), "", sprintf("%.1f%%", 100 * values)),
    p = .latents_format_p(values),
    logical = ifelse(is.na(values), "", ifelse(values, "yes", "no")),
    ci = {
      decimals <- .latents_column_decimals(x[[spec$decimals_from %||% spec$column[1L]]])
      low <- fixed(x[[spec$column[1L]]], decimals)
      high <- fixed(x[[spec$column[2L]]], decimals)
      low <- formatC(low, width = max(nchar(low)))
      high <- formatC(high, width = max(nchar(high)))
      ifelse(is.na(x[[spec$column[1L]]]), "", sprintf("[%s, %s]", low, high))
    })
}

.latents_default_display <- function(x) {
  lapply(names(x), function(name) {
    values <- x[[name]]
    format <- if (is.logical(values)) "logical" else if (is.numeric(values)) {
      if (grepl("(^|_)p_(value|adjusted)$", name)) "p" else
        if (all(is.na(values) | abs(values - round(values)) < 1e-9) &&
            !grepl("share|weight|probability|entropy|posterior", name)) "integer" else
          "number"
    } else "text"
    .latents_column(name, name, format)
  })
}

.latents_render <- function(x, n = 20L) {
  display <- attr(x, "display") %||% .latents_default_display(x)
  if (isTRUE(attr(x, "card")) && nrow(x) == 1L) return(.latents_render_card(x, display))
  marks <- attr(x, "marks")
  title <- attr(x, "title")
  frame <- as.data.frame(x)
  shown <- utils::head(frame, n)
  cells <- lapply(display, function(spec) .latents_cells(shown, spec))
  labels <- vapply(display, `[[`, character(1), "label")
  right <- vapply(display, function(spec) !spec$format %in% c("text", "label"), logical(1))
  widths <- vapply(seq_along(cells), function(j) {
    as.integer(max(nchar(labels[j], type = "width"), nchar(cells[[j]], type = "width"), 1L))
  }, integer(1))
  pad <- function(text, width, align_right) {
    gap <- strrep(" ", pmax(width - nchar(text, type = "width"), 0L))
    if (align_right) paste0(gap, text) else paste0(text, gap)
  }
  line_of <- function(values) {
    paste(vapply(seq_along(values), function(j) pad(values[j], widths[j], right[j]),
                 character(1)), collapse = "  ")
  }
  body <- vapply(seq_len(nrow(shown)), function(i) {
    line_of(vapply(cells, `[`, character(1), i))
  }, character(1))
  if (length(marks) > 0L) body <- paste0(body, utils::head(marks, nrow(shown)))
  c(if (!is.null(title)) c(title, ""),
    line_of(labels),
    paste(vapply(widths, function(w) strrep("-", w), character(1)), collapse = "  "),
    body,
    if (nrow(frame) > n) sprintf("... %d more rows", nrow(frame) - n))
}

print.latents_table <- function(x, n = 20L, ...) {
  if (nrow(x) == 0L) {
    cat(c(attr(x, "title"), "<no rows>"), sep = "\n")
    return(invisible(x))
  }
  cat(.latents_render(x, n), sep = "\n")
  invisible(x)
