print.multilpa <- function(x, rows = 20L, ...) {
  stopifnot(inherits(x, "multilpa"))
  ## A single-level fit has one observation per unit and one group class, so
  ## naming either would describe machinery rather than the model asked for.
  ## The header names the model that was fitted: a latent class analysis when
  ## every indicator is categorical, where a residual covariance means nothing,
  ## and a latent profile analysis otherwise.
  n_continuous <- length(.multilpa_continuous_names(x))
  n_categorical <- length(x$categorical %||% character())
  class_model <- n_continuous == 0L
  unit <- if (class_model) "class" else "profile"
  plural <- function(n, word) sprintf("%d %s%s", n, word,
                                      if (n == 1L) "" else if (endsWith(word, "s")) "es" else "s")
  kind <- if (class_model) "latent class analysis" else "latent profile analysis"
  if (isTRUE(x$single_level)) {
    cat(sprintf("%s%s: %s\n", toupper(substr(kind, 1L, 1L)), substring(kind, 2L),
                plural(x$n_profiles, unit)))
  } else {
    cat(sprintf("Two-level %s: %s, %s\n", kind, plural(x$n_profiles, unit),
                plural(x$n_group_classes, "group class")))
  }
  units <- if (isTRUE(x$single_level)) "observations" else
    sprintf("individuals in %d groups", x$n_groups)
  measurement <- if (class_model) {
    plural(n_categorical, "categorical indicator")
  } else {
    covariance_model <- x$covariance_model %||% "diagonal"
    paste0(if (!is.null(x$covariance_pattern)) {
      sprintf("%s diagonal residual covariance with covariances for %s (%s)",
              x$variance_model,
              paste(.latents_pattern_pairs(x$covariance_pattern), collapse = ", "),
              .latents_pattern_label(x))
    } else sprintf("%s %s residual covariance%s", x$variance_model,
                   covariance_model,
                   if (is.null(x$covariance_structure)) "" else
                     sprintf(" (%s)", x$covariance_structure)),
           if (n_categorical > 0L) sprintf(", %s",
             plural(n_categorical, "categorical indicator")) else "")
  }
  cat(sprintf("%d %s; %s\n", x$n_observations, units, measurement))
  .latents_print_extra(x)
  .latents_print_weights(x)
  if (class_model) {
    cat("Classes are labelled profile_1, profile_2, ... in every table.\n")
  }
  if (identical(x$centering %||% "none", "person")) {
    cat("Indicators person-centred, so the profiles are profiles of change\n")
  } else if (identical(x$centering %||% "none", "grand")) {
    cat("Indicators grand-centred, so the means are deviations from the overall mean\n")
  }
  if (!identical(x$scaling %||% "none", "none")) {
    cat(sprintf(paste("Indicators divided by their %s standard deviation, so",
                      "the means are in standard-deviation units\n"),
                if (identical(x$scaling, "person")) "within-person" else "overall"))
  }
  if (isTRUE(x$noise)) {
    cat(sprintf(paste("Noise component: proportion %.4f, %d observation%s",
                      "assigned to it (profile 0); hypervolume %.6g\n"),
                x$noise_probability, x$n_noise, if (x$n_noise == 1L) "" else "s",
                x$hypervolume))
  }
  if (!is.null(x$prior)) {
    cat(paste("Posterior mode under mclust's conjugate prior; the log likelihood",
              "and criteria below are unpenalized\n"))
  }
  cat(sprintf("Log likelihood: %.6f | AIC: %.3f | %s: %.3f\n",
              x$log_likelihood, x$aic,
              if (isTRUE(x$single_level)) "BIC" else "BIC (groups)", x$bic))
  if (identical(x$search, "emEM") && !is.null(x$n_screen)) {
    cat(sprintf(paste("Converged: %s | iterations: %d | best start: %d",
                      "(emEM: %d screened, %d run to the end)\n"),
                x$converged, x$iterations, x$best_start, x$n_screen, x$n_starts))
  } else {
    cat(sprintf("Converged: %s | iterations: %d | best start: %d/%d\n",
                x$converged, x$iterations, x$best_start, nrow(x$starts)))
  }
  if (!is.null(x$n_informative) && x$n_informative < x$n_observations) {
    cat(sprintf("%d row(s) carry no observed indicator; the individual-level BIC uses %d.\n",
                x$n_observations - x$n_informative, x$n_informative))
  }
  if (length(x$fixed %||% character()) > 0L) {
    cat(sprintf("Held fixed, not estimated here: %s%s\n",
                paste(x$fixed, collapse = ", "),
                if (isTRUE(x$staged)) " (first stage)" else ""))
    cat(sprintf("Parameters estimated here: %d; with the held measurement: %d\n",
                x$n_parameters,
                x$n_parameters_with_measurement %||% x$n_parameters))
  }
  if (x$boundary) cat("A variance is at its specified lower bound.\n")
  if (x$small_classes) cat("An effective class membership is below one.\n")
  .latents_print_gaussian_diagnostics(x$gaussian_diagnostics)
  .multilpa_print_primary(x, rows = rows)
  invisible(x)
}

as.data.frame.summary_multilpa <- function(x, row.names = NULL, optional = FALSE, ...) {
  stopifnot("`x` must be an object of class `summary_multilpa`" = inherits(x, "summary_multilpa"))
  .multilpa_coerce(x, row.names, list(...))
}

.multilpa_count_frame <- function(x) {
  individuals <- x$effective_profile_counts %||% colSums(x$subject_posteriors)
  if (isTRUE(x$noise)) {
    individuals <- c(individuals, noise = sum(x$noise_posteriors))
  }
  groups <- x$effective_group_counts
  if (is.null(groups) && !is.null(x$group_posteriors)) {
    groups <- colSums(x$group_posteriors)
  }
  counts <- Filter(Negate(is.null),
                   list(individuals = individuals, groups = groups))
  rows <- lapply(names(counts), function(level) {
    count <- unname(counts[[level]])
    classes <- seq_along(count)
    if (identical(level, "individuals") && isTRUE(x$noise)) {
      classes[length(classes)] <- 0L
    }
    data.frame(level = level, class = classes,
               effective_count = count,
               effective_proportion = count / sum(count))
  })
  result <- do.call(rbind, rows)
  row.names(result) <- NULL
  result
}

.multilpa_covariance_frame <- function(x) {
  vars <- .multilpa_continuous_names(x)
  n_indicators <- length(vars)
  n_profiles <- x$n_profiles
  if (n_indicators == 0L) {
    return(data.frame(profile = integer(), indicator = character(),
                      indicator_2 = character(), covariance = numeric()))
  }
  blocks <- lapply(seq_len(n_profiles), function(profile) {
    block <- if (is.null(x$covariances)) {
      diag(x$variances[profile, ], n_indicators, n_indicators)
    } else {
      matrix(x$covariances[, , profile], n_indicators, n_indicators)
    }
    data.frame(profile = profile,
               indicator = rep(vars, times = n_indicators),
               indicator_2 = rep(vars, each = n_indicators),
               covariance = as.vector(block))
  })
  do.call(rbind, blocks)
}

.multilpa_one <- function(value, absent) {
  if (is.null(value) || length(value) != 1L) absent else value
}

print.summary_multilpa <- function(x, digits = 4L, rows = 10L, ...) {
  stopifnot("`x` must be a `summary_multilpa` object" =
              inherits(x, "summary_multilpa"))
  .multilpa_check_print_arguments(digits, rows)
  # Named as print() names the fit: a latent class analysis when every
  # indicator is categorical, and a single-level fit without the one-row
  # groups and the single group class it was fitted through.
  class_model <- length(x$continuous) == 0L && length(x$categorical) > 0L
  kind <- if (class_model) "latent class analysis" else "latent profile analysis"
  plural <- function(n, word) {
    sprintf("%d %s%s", n, word,
            if (n == 1L) "" else if (endsWith(word, "s")) "es" else "s")
  }
  classes <- plural(x$n_profiles, if (class_model) "class" else "profile")
  if (isTRUE(x$single_level)) {
    cat(sprintf("%s%s: %s\n", toupper(substr(kind, 1L, 1L)), substring(kind, 2L),
                classes))
    cat(sprintf("Observations: %d; parameters: %d; converged: %s\n",
                x$n_observations, x$n_parameters, x$converged))
  } else {
    cat(sprintf("Two-level %s: %s, %s\n", kind, classes,
                plural(x$n_group_classes, "group class")))
    cat(sprintf("Individuals: %d; groups: %d; parameters: %d; converged: %s\n",
                x$n_observations, x$n_groups, x$n_parameters, x$converged))
  }
  if (length(x$fixed %||% character()) > 0L) {
    cat(sprintf("Held fixed%s: %s; parameters with the held measurement: %d\n",
                if (isTRUE(x$staged)) " from the first stage" else "",
                paste(x$fixed, collapse = ", "),
                x$n_parameters_with_measurement %||% x$n_parameters))
  }
  cat(sprintf("Log likelihood: %.6f; AIC: %.3f\nBIC (groups): %.3f; BIC (individuals): %.3f\n",
              x$log_likelihood, x$aic, x$bic, x$bic_individual))
  cat(sprintf("Best likelihood replicated in %d/%d starts (absolute tolerance %.3g).\n",
              x$n_best_replicated, x$n_starts %||% nrow(x$starts),
              x$replication_tolerance))
  if (!x$converged) cat("WARNING: best start did not converge.\n")
  if (x$boundary) cat("WARNING: at least one variance is at min_variance.\n")
  if (x$small_classes) cat("WARNING: an effective class membership is below one.\n")
  .multilpa_print_tables(x$tables, rows = rows, digits = digits)
  .multilpa_print_table_footer(x$tables)
  invisible(x)
}

logLik.multilpa <- function(object, ...) {
  stopifnot(inherits(object, "multilpa"))
  structure(object$log_likelihood, df = object$n_parameters,
            nobs = object$n_groups, class = "logLik")
}

nobs.multilpa <- function(object, ...) {
  stopifnot(inherits(object, "multilpa"))
  object$n_groups
}

print.multilpa_diagnostics <- function(x, ...) {
  stopifnot(inherits(x, "multilpa_diagnostics"))
  fit <- x$fit
  cat(sprintf("Classification quality: %d profile%s", fit$n_profiles,
              if (identical(as.integer(fit$n_profiles), 1L)) "" else "s"))
  one_group_class <- is.null(fit$n_group_classes) ||
    identical(as.integer(fit$n_group_classes), 1L)
  if (!one_group_class) cat(sprintf(", %d group classes", fit$n_group_classes))
  cat("\n\n")
  # `split()` orders alphabetically, which would print groups before
  # individuals on one line and after it on the next. The reporting order is
  # fixed once here so every line reads the same way.
  entropy <- x$entropy
  # With one group class the group level classifies nothing, so only the
  # individual level is worth a column.
  if (one_group_class) entropy <- entropy[entropy$level == "individuals", , drop = FALSE]
  levels_in_order <- entropy$level
  line <- function(label, values) {
    cat(sprintf("  %-20s %s\n", label, paste(values, collapse = "    ")))
  }
  per_level <- function(frame, f) {
    parts <- lapply(levels_in_order, function(level) {
      f(frame[frame$level == level, , drop = FALSE], level)
    })
    unlist(parts, use.names = FALSE)
  }
  line("Relative entropy",
       sprintf("%s %.3f", entropy$level, entropy$relative_entropy))
  line("Smallest class", per_level(x$classification, function(rows, level) {
    row <- rows[which.min(rows$estimated_proportion), , drop = FALSE]
    sprintf("%s %.1f (%.1f%%)", level, row$estimated_n,
            100 * row$estimated_proportion)
  }))
  averages <- x$average_posteriors
  assigned <- averages[averages$assigned_class == averages$class, , drop = FALSE]
  line("Lowest avg posterior", per_level(assigned, function(rows, level) {
    sprintf("%s %.3f", level, min(rows$average_posterior))
  }))
  if (is.null(x$residuals)) {
    line("Largest residual",
         if (isTRUE(fit$noise)) "not available for a fit with a noise component"
         else "not available for this model family")
  } else {
    worst <- x$residuals[which.max(abs(x$residuals$residual)), , drop = FALSE]
    line("Largest residual",
         sprintf("%.3f  (%s, %s; %s)", worst$residual, worst$indicator_1,
                 worst$indicator_2, worst$profile))
  }
  cat("\nTables: get_results(x, what = \"entropy\" | \"classification\" |",
      "\n        \"average_posteriors\" | \"residuals\" | \"all\").",
      "plot(x) draws them.\n")
  invisible(x)
}

.multilpa_reject_extra_arguments <- function(extra, verb, advice) {
  if (length(extra) == 0L) return(invisible(NULL))
  supplied <- names(extra)
  if (is.null(supplied)) supplied <- rep("", length(extra))
  labels <- ifelse(nzchar(supplied), sprintf("`%s`", supplied), "an unnamed argument")
  stop(errorCondition(
    sprintf("%s does not use %s. %s", verb, paste(labels, collapse = ", "), advice),
    class = "latents_bad_argument", call = NULL))
}

.latents_warn_unused_arguments <- function(extra, verb, advice) {
  if (length(extra) == 0L) return(invisible(NULL))
  supplied <- names(extra) %||% rep("", length(extra))
  labels <- ifelse(nzchar(supplied), sprintf("`%s`", supplied),
                   "an unnamed argument")
  warning(warningCondition(
    sprintf("%s ignores %s. %s", verb, paste(labels, collapse = ", "), advice),
    class = "latents_unused_argument", call = NULL))
  invisible(NULL)
}

.latents_former_argument <- function(current, current_given, former, names) {
  if (is.null(former)) return(current)
  if (current_given) {
    stop(errorCondition(sprintf(paste(
      "`%s` and `%s` are the same argument (`%s` is its name in latents",
      "0.9.21); give one of them."), names[1L], names[2L], names[2L]),
      class = "latents_bad_argument", call = NULL))
  }
  former
}

.multilpa_supported_views <- function(x) {
  # Ask the method that will be called what it accepts, rather than assuming
  # every class takes the full catalogue. A covariate fit's plot method offers
  # "profiles" and "sequences" only, so report() must not hand it a view it has
  # never heard of.
  method <- .multilpa_plot_method(x)
  if (is.null(method)) return(character())
  # A method with no `what` draws one thing. `NA_character_` stands for "call
  # plot() with no view", which `report()` passes through as a bare plot(x).
  if (!"what" %in% names(formals(method))) return(NA_character_)
  # `"all"` is a request to draw every view, not a view, so it is dropped
  # before the list is walked: leaving it in would make both `report()` and
  # `plot(what = "all")` call themselves.
  candidates <- setdiff(eval(formals(method)$what), "all")
  Filter(function(view) {
    if (identical(view, "responses")) return(length(x$categorical) > 0L)
    if (identical(view, "sequences")) return(!is.null(x$time))
    if (identical(view, "profiles") &&
        length(.multilpa_continuous_names(x)) == 0L &&
        length(x$response_probabilities) > 0L) {
      return(tryCatch({ .gg_category_scores(x$response_probabilities); TRUE },
                      latents_bad_argument = function(e) FALSE))
    }
    # The heatmap draws the response probabilities when there are no means.
    if (identical(view, "heatmap") && length(x$response_probabilities) > 0L) {
      return(TRUE)
    }
    if (view %in% c("profiles", "bars", "heatmap")) {
      return(!is.null(x$means) && ncol(x$means) > 0L)
    }
    # The case-level views draw the stored indicators, which a centred fit
    # does not sit on, and the two multi-indicator views need two of them.
    if (view %in% c("raincloud", "parallel", "pairs")) {
      enough <- if (identical(view, "raincloud")) 1L else 2L
      return(!is.null(x$indicator_data) &&
               length(.multilpa_continuous_names(x)) >= enough &&
               !.multilpa_is_transformed(x))
    }
    if (identical(view, "probabilities")) return(!is.null(x$profile_probabilities))
    # The two case-level diagnostics separate cases by profile, so a
    # single-profile fit has nothing for them to separate: every case sits in
    # the one profile with probability one.
    if (view %in% c("entropy", "posteriors")) {
      return(!is.null(x$subject_posteriors) && ncol(x$subject_posteriors) > 1L)
    }
    TRUE
  }, candidates)
}

.multilpa_available_views_text <- function(x) {
  views <- .multilpa_supported_views(x)
  if (length(views) == 0L) return("none")
  paste(ifelse(is.na(views), "the default plot", views), collapse = ", ")
}

